#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-only
# StGit (Stacked Git) - Python implementation

import sys
import os
import re
import json
import subprocess
import tempfile
import shutil
import hashlib
import time
import textwrap
from datetime import datetime, timezone, timedelta
from pathlib import Path

VERSION = "2.5.5"

# ============================================================
# Color support
# ============================================================

class Color:
    RESET = "\033[0m"
    BOLD = "\033[1m"
    DIM = "\033[2m"
    ITALIC = "\033[3m"
    GREEN = "\033[32m"
    BLUE = "\033[34m"
    MAGENTA = "\033[35m"
    RED = "\033[31m"

_color_enabled = None

def _setup_color(when):
    global _color_enabled
    if when == 'always' or when == 'ansi':
        _color_enabled = True
    elif when == 'never':
        _color_enabled = False
    else:  # auto
        no_color = os.environ.get('NO_COLOR', '')
        _color_enabled = sys.stdout.isatty() and not no_color

def colorize(s, *attrs):
    if not _color_enabled:
        return s
    prefix = ''.join(attrs)
    return f"{Color.RESET}{prefix}{s}{Color.RESET}"

# ============================================================
# Git operations
# ============================================================

_C_args = []  # -C path args

def git(*args, input=None, check=True, capture=True, env=None):
    """Run a git command"""
    cmd = ['git'] + list(_C_args) + list(args)
    kwargs = {}
    if capture:
        kwargs['stdout'] = subprocess.PIPE
        kwargs['stderr'] = subprocess.PIPE
    if input is not None:
        kwargs['input'] = input if isinstance(input, bytes) else input.encode()

    if env is not None:
        kwargs['env'] = {**os.environ, **env}

    result = subprocess.run(cmd, **kwargs)
    if check and result.returncode != 0:
        stderr = result.stderr.decode() if capture and result.stderr else ''
        raise GitError(f"git {' '.join(args)} failed: {stderr.strip()}")
    return result

def git_output(*args, **kwargs):
    """Run git and return stdout as string"""
    result = git(*args, **kwargs)
    return result.stdout.decode().rstrip('\n')

def git_lines(*args, **kwargs):
    """Run git and return list of lines"""
    output = git_output(*args, **kwargs)
    if not output:
        return []
    return output.split('\n')

def git_bool(*args, **kwargs):
    """Run git and return True/False based on exit code"""
    result = git(*args, check=False, **kwargs)
    return result.returncode == 0

class GitError(Exception):
    pass

class StgError(Exception):
    def __init__(self, msg, code=2):
        super().__init__(msg)
        self.code = code

def get_git_dir():
    """Get the git directory"""
    try:
        return git_output('rev-parse', '--git-dir')
    except GitError:
        raise StgError("not a git repository")

def get_work_tree():
    """Get the work tree"""
    try:
        return git_output('rev-parse', '--show-toplevel')
    except GitError:
        return None

def resolve_ref(ref):
    """Resolve a ref to a hash"""
    try:
        return git_output('rev-parse', '--verify', ref)
    except GitError:
        return None

def ref_exists(ref):
    """Check if a ref exists"""
    return resolve_ref(ref) is not None

def get_head():
    """Get HEAD hash"""
    return resolve_ref('HEAD')

def get_current_branch():
    """Get current branch name"""
    try:
        symbolic = git_output('symbolic-ref', 'HEAD')
        if symbolic.startswith('refs/heads/'):
            return symbolic[len('refs/heads/'):]
        return None
    except GitError:
        return None

def get_branches():
    """Get all local branches"""
    try:
        lines = git_lines('for-each-ref', '--format=%(refname:short)', 'refs/heads/')
        return [l for l in lines if l]
    except GitError:
        return []

def hash_object(data, obj_type='blob'):
    """Hash an object and write it to the object store"""
    if isinstance(data, str):
        data = data.encode()
    result = git('hash-object', '-w', '-t', obj_type, '--stdin', input=data)
    return result.stdout.decode().strip()

def make_tree(entries):
    """Create a tree object from a list of (mode, type, hash, name) tuples"""
    # entries: list of (mode, type, oid, name)
    lines = []
    for mode, typ, oid, name in entries:
        lines.append(f'{mode} {typ} {oid}\t{name}')
    content = '\n'.join(lines) + '\n'
    result = git('mktree', input=content)
    return result.stdout.decode().strip()

def make_commit(tree, parents, author_name, author_email, author_date,
                committer_name, committer_email, committer_date, message):
    """Create a commit object"""
    if isinstance(author_date, datetime):
        author_date_str = format_git_date(author_date)
    else:
        author_date_str = str(author_date)

    if isinstance(committer_date, datetime):
        committer_date_str = format_git_date(committer_date)
    else:
        committer_date_str = str(committer_date)

    env = {
        'GIT_AUTHOR_NAME': author_name,
        'GIT_AUTHOR_EMAIL': author_email,
        'GIT_AUTHOR_DATE': author_date_str,
        'GIT_COMMITTER_NAME': committer_name,
        'GIT_COMMITTER_EMAIL': committer_email,
        'GIT_COMMITTER_DATE': committer_date_str,
    }

    cmd = ['commit-tree', tree]
    for p in parents:
        cmd += ['-p', p]
    cmd += ['-m', message]

    result = git(*cmd, env=env)
    return result.stdout.decode().strip()

def format_git_date(dt):
    """Format a datetime as git date string"""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    ts = int(dt.timestamp())
    offset = dt.utcoffset()
    if offset is None:
        offset_str = '+0000'
    else:
        total_seconds = int(offset.total_seconds())
        sign = '+' if total_seconds >= 0 else '-'
        total_seconds = abs(total_seconds)
        h = total_seconds // 3600
        m = (total_seconds % 3600) // 60
        offset_str = f'{sign}{h:02d}{m:02d}'
    return f'{ts} {offset_str}'

def parse_git_date(s):
    """Parse a git timestamp like '1234567890 +0200' to datetime"""
    parts = s.strip().split()
    ts = int(parts[0])
    if len(parts) > 1:
        tz_str = parts[1]
        sign = 1 if tz_str[0] == '+' else -1
        h = int(tz_str[1:3])
        m = int(tz_str[3:5])
        tz = timezone(timedelta(hours=sign*h, minutes=sign*m))
    else:
        tz = timezone.utc
    return datetime.fromtimestamp(ts, tz=tz)

def get_cat_file(oid, kind=None):
    """Get the content of a git object"""
    if kind:
        return git_output('cat-file', kind, oid)
    else:
        result = git('cat-file', '-p', oid)
        return result.stdout.decode()

def read_tree_to_index(tree):
    """Read a tree into the index"""
    git('read-tree', tree)

def update_ref(ref, new_hash, old_hash=None):
    """Update a ref"""
    cmd = ['update-ref', ref, new_hash]
    if old_hash:
        cmd.append(old_hash)
    git(*cmd)

def delete_ref(ref):
    """Delete a ref"""
    git('update-ref', '-d', ref)

def get_config(key):
    """Get a git config value"""
    try:
        return git_output('config', '--local', key)
    except GitError:
        return None

def set_config(key, value):
    """Set a git config value"""
    git('config', '--local', key, value)

def unset_config(key):
    """Unset a git config value"""
    git('config', '--local', '--unset', key, check=False)

def get_user_name():
    """Get user name from git config"""
    try:
        return git_output('config', 'user.name')
    except GitError:
        return os.environ.get('GIT_COMMITTER_NAME', os.environ.get('USER', 'Unknown'))

def get_user_email():
    """Get user email from git config"""
    try:
        return git_output('config', 'user.email')
    except GitError:
        return os.environ.get('GIT_COMMITTER_EMAIL', 'unknown@unknown')

def get_commit_info(oid):
    """Get commit information"""
    result = git('cat-file', '-p', oid)
    content = result.stdout.decode()
    lines = content.split('\n')
    info = {}
    i = 0
    while i < len(lines) and lines[i]:
        line = lines[i]
        if line.startswith('tree '):
            info['tree'] = line[5:]
        elif line.startswith('parent '):
            info.setdefault('parents', []).append(line[7:])
        elif line.startswith('author '):
            info['author'] = parse_identity_line(line[7:])
        elif line.startswith('committer '):
            info['committer'] = parse_identity_line(line[10:])
        i += 1
    # Rest is message
    message = '\n'.join(lines[i+1:])
    info['message'] = message
    return info

def parse_identity_line(line):
    """Parse 'Name <email> timestamp tzoffset' """
    # e.g., "John Doe <john@doe.com> 1234567890 +0000"
    m = re.match(r'^(.*?)\s+<([^>]*)>\s+(\d+\s+[+-]\d{4})$', line)
    if m:
        return {
            'name': m.group(1),
            'email': m.group(2),
            'date': parse_git_date(m.group(3)),
        }
    # Fallback
    m = re.match(r'^(.*?)\s+<([^>]*)>\s+(\d+)$', line)
    if m:
        return {
            'name': m.group(1),
            'email': m.group(2),
            'date': parse_git_date(m.group(3)),
        }
    return {'name': line, 'email': '', 'date': datetime.now(tz=timezone.utc)}

def get_tree_entries(tree_oid):
    """Get tree entries as list of (mode, type, oid, name)"""
    try:
        result = git('ls-tree', tree_oid)
        entries = []
        for line in result.stdout.decode().split('\n'):
            if not line:
                continue
            # format: "100644 blob abc123\tfilename"
            parts = line.split('\t', 1)
            if len(parts) != 2:
                continue
            meta, name = parts
            meta_parts = meta.split()
            if len(meta_parts) == 3:
                mode, typ, oid = meta_parts
                entries.append((mode, typ, oid, name))
        return entries
    except GitError:
        return []

def apply_diff(diff_text, base=None, strip=1, context=None, reject=False, threeway=False):
    """Apply a diff using git apply"""
    cmd = ['apply']
    if strip is not None and strip != 1:
        cmd += [f'-p{strip}']
    if context is not None:
        cmd += [f'-C{context}']
    if reject:
        cmd += ['--reject']
    if threeway:
        cmd += ['--3way']
    cmd += ['-']
    result = git(*cmd, input=diff_text, check=False)
    return result.returncode == 0, result.stderr.decode()

def merge_recursive(base, head, merge):
    """Perform a 3-way merge"""
    result = git('merge-recursive', base, '--', head, merge, check=False)
    return result.returncode == 0

# ============================================================
# Stack state management
# ============================================================

STACK_VERSION = 5

class PatchDescriptor:
    """Describes a patch stored in the patches/ tree"""
    def __init__(self, bottom, top, author_name, author_email, author_date, message):
        self.bottom = bottom  # tree hash
        self.top = top        # tree hash  
        self.author_name = author_name
        self.author_email = author_email
        self.author_date = author_date  # datetime
        self.message = message

    def to_blob(self):
        """Convert to the blob format stored in patches/"""
        if isinstance(self.author_date, datetime):
            date_str = self.author_date.strftime('%Y-%m-%d %H:%M:%S %z')
        else:
            date_str = str(self.author_date)
        lines = [
            f"Bottom: {self.bottom}",
            f"Top:    {self.top}",
            f"Author: {self.author_name} <{self.author_email}>",
            f"Date:   {date_str}",
            "",
            self.message,
        ]
        return '\n'.join(lines)

    @classmethod
    def from_blob(cls, content):
        """Parse from blob content"""
        lines = content.split('\n')
        bottom = top = author_name = author_email = ''
        author_date = datetime.now(tz=timezone.utc)

        i = 0
        while i < len(lines):
            line = lines[i]
            if line.startswith('Bottom: '):
                bottom = line[8:].strip()
            elif line.startswith('Top:    '):
                top = line[8:].strip()
            elif line.startswith('Author: '):
                m = re.match(r'Author: (.*?)\s*<([^>]*)>', line)
                if m:
                    author_name = m.group(1).strip()
                    author_email = m.group(2)
            elif line.startswith('Date:   '):
                date_str = line[8:].strip()
                try:
                    # Parse "YYYY-MM-DD HH:MM:SS +ZZZZ"
                    m = re.match(r'(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) ([+-]\d{4})', date_str)
                    if m:
                        dt_part = m.group(1)
                        tz_part = m.group(2)
                        sign = 1 if tz_part[0] == '+' else -1
                        h = int(tz_part[1:3])
                        mn = int(tz_part[3:5])
                        tz = timezone(timedelta(hours=sign*h, minutes=sign*mn))
                        author_date = datetime.strptime(dt_part, '%Y-%m-%d %H:%M:%S').replace(tzinfo=tz)
                except Exception:
                    pass
            elif line == '' and i < len(lines) - 1:
                # Rest is message
                message = '\n'.join(lines[i+1:])
                break
            i += 1
        else:
            message = ''

        return cls(bottom, top, author_name, author_email, author_date, message)


class StackState:
    """Represents the state of a StGit stack"""

    def __init__(self, head, applied, unapplied, hidden, patches, prev=None):
        self.head = head        # commit hash that HEAD points to
        self.applied = applied  # list of patch names (bottom to top)
        self.unapplied = unapplied  # list of patch names
        self.hidden = hidden    # list of patch names
        self.patches = patches  # dict: name -> commit hash
        self.prev = prev        # previous state commit hash (the merge commit)

    def to_dict(self):
        return {
            'version': STACK_VERSION,
            'prev': self.prev,
            'head': self.head,
            'applied': self.applied,
            'unapplied': self.unapplied,
            'hidden': self.hidden,
            'patches': {name: {'oid': oid} for name, oid in self.patches.items()},
        }

    def to_json(self):
        return json.dumps(self.to_dict(), indent=2)

    @classmethod
    def from_dict(cls, d):
        patches = {name: info['oid'] for name, info in d.get('patches', {}).items()}
        return cls(
            head=d['head'],
            applied=d.get('applied', []),
            unapplied=d.get('unapplied', []),
            hidden=d.get('hidden', []),
            patches=patches,
            prev=d.get('prev'),
        )

    @classmethod
    def from_json(cls, content):
        return cls.from_dict(json.loads(content))

    def top_patch(self):
        """Return the top applied patch name or None"""
        if self.applied:
            return self.applied[-1]
        return None

    def all_patch_names(self):
        """Return all patch names in order"""
        return self.applied + self.unapplied + self.hidden

    def is_applied(self, name):
        return name in self.applied

    def is_unapplied(self, name):
        return name in self.unapplied

    def is_hidden(self, name):
        return name in self.hidden

    def patch_exists(self, name):
        return name in self.patches

    def get_base(self):
        """Get the base commit (commit below the stack)"""
        if self.applied:
            bottom_patch = self.applied[0]
            oid = self.patches[bottom_patch]
            info = get_commit_info(oid)
            return info['parents'][0] if info.get('parents') else None
        else:
            return self.head

    def copy(self):
        """Make a copy of the state"""
        return StackState(
            head=self.head,
            applied=list(self.applied),
            unapplied=list(self.unapplied),
            hidden=list(self.hidden),
            patches=dict(self.patches),
            prev=self.prev,
        )


class Stack:
    """Manages a StGit stack for a branch"""

    def __init__(self, branch):
        self.branch = branch
        self.ref = f'refs/stacks/{branch}'
        self._state = None
        self._patch_descs = {}  # cache: name -> PatchDescriptor

    def is_initialized(self):
        return ref_exists(self.ref)

    def get_state(self):
        """Get current stack state"""
        if self._state is None:
            self._state = self._load_state()
        return self._state

    def _load_state(self):
        """Load state from the stack ref"""
        if not self.is_initialized():
            raise StgError(f"branch `{self.branch}` is not initialized")

        try:
            json_content = git_output('cat-file', '-p', f'{self.ref}^{{tree}}:stack.json')
            return StackState.from_json(json_content)
        except GitError as e:
            raise StgError(f"failed to load stack state: {e}")

    def get_patch_desc(self, name):
        """Get patch descriptor for a patch"""
        if name in self._patch_descs:
            return self._patch_descs[name]

        try:
            content = git_output('cat-file', '-p', f'{self.ref}^{{tree}}:patches/{name}')
            desc = PatchDescriptor.from_blob(content)
            self._patch_descs[name] = desc
            return desc
        except GitError:
            return None

    def get_patch_desc_from_tree(self, tree_oid, name):
        """Get patch descriptor from a specific state tree"""
        try:
            content = git_output('cat-file', '-p', f'{tree_oid}:patches/{name}')
            return PatchDescriptor.from_blob(content)
        except GitError:
            return None

    def save_state(self, state, message, committer_date=None):
        """Save a new state to the stack ref"""
        self._save_state_impl(state, message, committer_date)
        self._state = state
        self._patch_descs = {}  # clear cache

    def _save_state_impl(self, state, message, committer_date=None):
        """Internal: save state and update refs/stacks/branch"""
        if committer_date is None:
            committer_date = datetime.now(tz=timezone.utc)

        name = get_user_name()
        email = get_user_email()

        # Build patches tree
        patch_entries = []
        for pname, poid in state.patches.items():
            # Get patch descriptor
            desc = self._patch_descs.get(pname)
            if desc is None:
                # Try to get from current ref tree
                try:
                    content = git_output('cat-file', '-p', f'{self.ref}^{{tree}}:patches/{pname}')
                    desc = PatchDescriptor.from_blob(content)
                    self._patch_descs[pname] = desc
                except GitError:
                    pass

            if desc is not None:
                blob_content = desc.to_blob()
                blob_hash = hash_object(blob_content)
                patch_entries.append(('100644', 'blob', blob_hash, pname))

        if patch_entries:
            patches_tree = make_tree(patch_entries)
        else:
            patches_tree = git_output('hash-object', '-w', '-t', 'tree', '--stdin', input='')

        # Build stack.json
        json_str = state.to_json()
        json_hash = hash_object(json_str)

        # Build state tree
        state_tree = make_tree([
            ('040000', 'tree', patches_tree, 'patches'),
            ('100644', 'blob', json_hash, 'stack.json'),
        ])

        # Get previous state commit
        prev_state_commit = None
        if self.is_initialized():
            # Get the current state commit (parent[0] of the merge commit)
            try:
                merge_info = get_commit_info(self.ref)
                if merge_info.get('parents'):
                    prev_state_commit = merge_info['parents'][0]
            except Exception:
                pass

        # Create new state commit (single parent = prev state commit)
        state_parents = []
        if prev_state_commit:
            state_parents = [prev_state_commit]

        state_commit = make_commit(
            state_tree, state_parents,
            name, email, committer_date,
            name, email, committer_date,
            message
        )

        # Get old HEAD (from previous state or current HEAD)
        old_head = None
        if self.is_initialized():
            try:
                old_state = self._load_state()
                old_head = old_state.head
            except Exception:
                old_head = get_head()

        # Create merge commit
        # Parents: [state_commit, new_head, old_head, prev_merge_commit, ...]
        merge_parents = [state_commit, state.head]
        if old_head and old_head != state.head:
            merge_parents.append(old_head)
        if self.is_initialized():
            try:
                current_merge = git_output('rev-parse', self.ref)
                if current_merge not in merge_parents:
                    merge_parents.append(current_merge)
            except Exception:
                pass

        # Remove duplicates while preserving order
        seen = set()
        unique_parents = []
        for p in merge_parents:
            if p not in seen:
                seen.add(p)
                unique_parents.append(p)

        # Update state.prev to the current merge commit before creating new one
        if self.is_initialized():
            try:
                state.prev = git_output('rev-parse', self.ref)
            except Exception:
                state.prev = None

        # Rebuild json with updated prev
        json_str = state.to_json()
        json_hash = hash_object(json_str)
        state_tree = make_tree([
            ('040000', 'tree', patches_tree, 'patches'),
            ('100644', 'blob', json_hash, 'stack.json'),
        ])

        # Recreate state commit with updated tree
        state_commit = make_commit(
            state_tree, state_parents,
            name, email, committer_date,
            name, email, committer_date,
            message
        )

        # Recreate merge parents with new state commit
        unique_parents[0] = state_commit

        merge_commit = make_commit(
            state_tree, unique_parents,
            name, email, committer_date,
            name, email, committer_date,
            message
        )

        # Update the stack ref
        update_ref(self.ref, merge_commit)

    def initialize(self, head_commit=None):
        """Initialize the stack"""
        if head_commit is None:
            head_commit = get_head()

        state = StackState(
            head=head_commit,
            applied=[],
            unapplied=[],
            hidden=[],
            patches={},
            prev=None,
        )

        # For initialize, we need to create the ref specially
        # First time, prev = null, so we make the state commit with no parents
        name = get_user_name()
        email = get_user_email()
        now = datetime.now(tz=timezone.utc)

        # Create empty patches tree
        empty_tree = git_output('hash-object', '-w', '-t', 'tree', '--stdin', input='')

        # Create stack.json blob
        json_str = state.to_json()
        json_hash = hash_object(json_str)

        # Create state tree
        state_tree = make_tree([
            ('040000', 'tree', empty_tree, 'patches'),
            ('100644', 'blob', json_hash, 'stack.json'),
        ])

        # Create state commit with no parents
        state_commit = make_commit(
            state_tree, [],
            name, email, now,
            name, email, now,
            'initialize'
        )

        # Create merge commit (parents: state_commit, head_commit)
        merge_commit = make_commit(
            state_tree, [state_commit, head_commit],
            name, email, now,
            name, email, now,
            'initialize'
        )

        # Update state.prev now
        state.prev = None  # it's the initial state

        # Update ref
        update_ref(self.ref, merge_commit)
        self._state = state

    def get_log_entries(self, branch_override=None):
        """Get log entries as list of (hash, date, message)"""
        ref = f'refs/stacks/{branch_override or self.branch}'
        if not ref_exists(ref):
            return []

        entries = []
        # Get state commit (parent[0] of merge commit)
        try:
            merge_info = get_commit_info(ref)
        except Exception:
            return []

        if not merge_info.get('parents'):
            return []

        state_commit = merge_info['parents'][0]

        while state_commit:
            try:
                commit_info = get_commit_info(state_commit)
                author = commit_info.get('author', {})
                date = author.get('date', datetime.now(tz=timezone.utc))
                message = commit_info.get('message', '').strip().split('\n')[0]
                entries.append((state_commit, date, message, commit_info.get('tree')))

                # Get next via stack.json.prev
                tree = commit_info.get('tree')
                if tree:
                    try:
                        json_content = git_output('cat-file', '-p', f'{tree}:stack.json')
                        state_data = json.loads(json_content)
                        prev_merge = state_data.get('prev')
                        if prev_merge:
                            # Get state commit from merge commit
                            prev_merge_info = get_commit_info(prev_merge)
                            if prev_merge_info.get('parents'):
                                state_commit = prev_merge_info['parents'][0]
                            else:
                                state_commit = None
                        else:
                            state_commit = None
                    except Exception:
                        state_commit = None
                else:
                    state_commit = None
            except Exception:
                break

        return entries

    def get_patch_state_from_commit(self, state_commit):
        """Get StackState from a state commit hash"""
        try:
            commit_info = get_commit_info(state_commit)
            tree = commit_info['tree']
            json_content = git_output('cat-file', '-p', f'{tree}:stack.json')
            return StackState.from_json(json_content), tree
        except Exception as e:
            raise StgError(f"failed to get state from commit: {e}")


