def apply_patch_to_tree(patch_tree, base_tree, current_tree):
    """Apply a patch (from base_tree to patch_tree) onto current_tree"""
    # This is a 3-way merge: base=base_tree, ours=current_tree, theirs=patch_tree
    result = git('merge-tree', base_tree, current_tree, patch_tree, check=False)
    output = result.stdout.decode()

    if result.returncode != 0:
        return None, False, output

    # Parse merge-tree output
    # First line is the resulting tree
    lines = output.strip().split('\n') if output.strip() else []
    if lines:
        new_tree = lines[0]
        has_conflicts = len(lines) > 1
        return new_tree, not has_conflicts, output
    return None, False, output

# ============================================================
# Push/Pop operations
# ============================================================

def push_patch(stack, state, patch_name, committer_date=None, merged=False):
    """Push a single patch onto the stack"""
    if patch_name not in state.unapplied and patch_name not in state.hidden:
        raise StgError(f"patch `{patch_name}` is not unapplied")

    if committer_date is None:
        committer_date = datetime.now(tz=timezone.utc)

    old_oid = state.patches[patch_name]
    old_commit_info = get_commit_info(old_oid)
    old_tree = old_commit_info['tree']
    old_parent = old_commit_info['parents'][0] if old_commit_info.get('parents') else None

    # Get current head (where we're applying on top of)
    current_head = state.head

    # If no changes (empty patch or set-tree)
    if old_parent == old_tree:
        # Empty patch - just re-parent
        author = old_commit_info['author']
        new_oid = make_commit(
            old_tree, [current_head],
            author['name'], author['email'], author['date'],
            get_user_name(), get_user_email(), committer_date,
            old_commit_info['message']
        )
    else:
        # Apply the patch changes on top of current head
        current_head_info = get_commit_info(current_head)
        current_tree = current_head_info['tree']

        # 3-way merge: base=old_parent_tree, ours=current_tree, theirs=old_tree
        old_parent_info = get_commit_info(old_parent) if old_parent else None
        old_parent_tree = old_parent_info['tree'] if old_parent_info else old_tree

        if old_parent_tree == current_tree:
            # Fast-forward: just use old_tree directly
            new_tree = old_tree
            has_conflicts = False
        else:
            # Need to merge
            result = git('merge-tree', '--write-tree', old_parent_tree, current_tree, old_tree, check=False)
            output = result.stdout.decode().strip()
            lines = output.split('\n') if output else []

            if lines:
                new_tree = lines[0].strip()
                has_conflicts = result.returncode != 0
            else:
                new_tree = current_tree
                has_conflicts = True

            if has_conflicts:
                # Apply conflicts to working tree
                result2 = git('merge-tree', '--write-tree', '-z', old_parent_tree, current_tree, old_tree, check=False)
                # Fall back: do it differently
                return None, True, "conflicts"

        author = old_commit_info['author']
        new_oid = make_commit(
            new_tree, [current_head],
            author['name'], author['email'], author['date'],
            get_user_name(), get_user_email(), committer_date,
            old_commit_info['message']
        )

    # Update state
    if patch_name in state.unapplied:
        state.unapplied.remove(patch_name)
    elif patch_name in state.hidden:
        state.hidden.remove(patch_name)
    state.applied.append(patch_name)
    state.patches[patch_name] = new_oid
    state.head = new_oid

    return new_oid, False, None

def pop_patch(stack, state, patch_name, committer_date=None, keep=False):
    """Pop a patch from the stack"""
    if patch_name not in state.applied:
        raise StgError(f"patch `{patch_name}` is not applied")

    if committer_date is None:
        committer_date = datetime.now(tz=timezone.utc)

    # Pop all patches above this one first
    idx = state.applied.index(patch_name)
    patches_to_pop = list(reversed(state.applied[idx:]))

    # The new head will be the parent of the bottom-most patch being popped
    if idx > 0:
        new_head = state.patches[state.applied[idx - 1]]
    else:
        new_head = state.get_base()

    # Move patches from applied to unapplied
    for pname in patches_to_pop:
        state.applied.remove(pname)
        state.unapplied.insert(0, pname)

    state.head = new_head
    return new_head


