def main():
    global _C_args

    args = sys.argv[1:]

    # Process global options
    color_when = 'auto'
    remaining = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--version':
            cmd_version([])
            return
        elif arg in ('-h', '--help'):
            cmd_help_main()
            return
        elif arg == '--color':
            i += 1
            if i < len(args):
