        'pull': cmd_pull,
        'rebase': cmd_rebase,
        'repair': cmd_repair,
        'reset': cmd_reset,
        'undo': cmd_undo,
        'redo': cmd_redo,
        'spill': cmd_spill,
        'patches': cmd_patches,
        'email': cmd_email,
        'completion': cmd_completion,
        # Aliases
        'add': cmd_alias_add,
        'mv': cmd_alias_mv,
        'resolved': cmd_alias_resolved,
        'rm': cmd_alias_rm,
        'status': cmd_alias_status,
    }

    if cmd not in dispatch:
        print(f"error: unknown command `{cmd}`", file=sys.stderr)
        sys.exit(2)

    try:
        dispatch[cmd](cmd_args)
    except StgError as e:
