    """Get user email from git config"""
    try:
        return git_output('config', 'user.email')
    except GitError:
        return os.environ.get('GIT_COMMITTER_EMAIL', 'unknown@unknown')

def get_commit_info(oid):
    """Get commit information"""
    result = git('cat-file', '-p', oid)
    content = result.stdout.decode()
    lines = content.split('\n')
    info = {}
    i = 0
    while i < len(lines) and lines[i]:
        line = lines[i]
        if line.startswith('tree '):
            info['tree'] = line[5:]
        elif line.startswith('parent '):
            info.setdefault('parents', []).append(line[7:])
        elif line.startswith('author '):
            info['author'] = parse_identity_line(line[7:])
        elif line.startswith('committer '):
            info['committer'] = parse_identity_line(line[10:])
        i += 1
    # Rest is message
    message = '\n'.join(lines[i+1:])
    info['message'] = message
    return info

def parse_identity_line(line):
    """Parse 'Name <email> timestamp tzoffset' """
    # e.g., "John Doe <john@doe.com> 1234567890 +0000"
    m = re.match(r'^(.*?)\s+<([^>]*)>\s+(\d+\s+[+-]\d{4})$', line)
    if m:
        return {
            'name': m.group(1),
            'email': m.group(2),
            'date': parse_git_date(m.group(3)),
        }
    # Fallback
    m = re.match(r'^(.*?)\s+<([^>]*)>\s+(\d+)$', line)
    if m:
        return {
            'name': m.group(1),
            'email': m.group(2),
            'date': parse_git_date(m.group(3)),
        }
    return {'name': line, 'email': '', 'date': datetime.now(tz=timezone.utc)}

def get_tree_entries(tree_oid):
    """Get tree entries as list of (mode, type, oid, name)"""
    try:
        result = git('ls-tree', tree_oid)
        entries = []
        for line in result.stdout.decode().split('\n'):
            if not line:
                continue
            # format: "100644 blob abc123\tfilename"
            parts = line.split('\t', 1)
            if len(parts) != 2:
                continue
            meta, name = parts
            meta_parts = meta.split()
            if len(meta_parts) == 3:
                mode, typ, oid = meta_parts
                entries.append((mode, typ, oid, name))
        return entries
    except GitError:
        return []

def apply_diff(diff_text, base=None, strip=1, context=None, reject=False, threeway=False):
    """Apply a diff using git apply"""
    cmd = ['apply']
    if strip is not None and strip != 1:
        cmd += [f'-p{strip}']
    if context is not None:
        cmd += [f'-C{context}']
    if reject:
        cmd += ['--reject']
    if threeway:
        cmd += ['--3way']
    cmd += ['-']
    result = git(*cmd, input=diff_text, check=False)
    return result.returncode == 0, result.stderr.decode()

def merge_recursive(base, head, merge):
    """Perform a 3-way merge"""
    result = git('merge-recursive', base, '--', head, merge, check=False)
    return result.returncode == 0

