# Patch description editor
# ============================================================

def get_editor():
    """Get the editor to use"""
    # Check various config options
    for env in ['GIT_EDITOR', 'VISUAL', 'EDITOR']:
        if env in os.environ:
            return os.environ[env]
    try:
        return git_output('config', 'core.editor')
    except GitError:
        pass
    return 'vi'

def edit_file(path):
    """Open a file in the editor"""
    editor = get_editor()
    os.system(f'{editor} "{path}"')

def parse_patch_template(content):
    """Parse a patch template and return (name, author_name, author_email, author_date, message)"""
    lines = content.split('\n')
    patch_name = None
    author_name = None
    author_email = None
    author_date = None
    msg_lines = []
    in_body = False

    for line in lines:
        if line.startswith('#'):
            continue
        if not in_body:
            if line.startswith('Patch:  '):
                patch_name = line[8:].strip()
            elif line.startswith('Author: '):
                m = re.match(r'Author: (.*?)\s*<([^>]*)>', line)
                if m:
                    author_name = m.group(1).strip()
                    author_email = m.group(2)
            elif line.startswith('Date:   '):
                date_str = line[8:].strip()
                try:
                    m = re.match(r'(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) ([+-]\d{4})', date_str)
                    if m:
                        dt_part = m.group(1)
                        tz_part = m.group(2)
                        sign = 1 if tz_part[0] == '+' else -1
                        h = int(tz_part[1:3])
                        mn = int(tz_part[3:5])
                        tz = timezone(timedelta(hours=sign*h, minutes=sign*mn))
                        author_date = datetime.strptime(dt_part, '%Y-%m-%d %H:%M:%S').replace(tzinfo=tz)
                except Exception:
                    pass
            elif line == '':
                in_body = True
        else:
            msg_lines.append(line)

    message = '\n'.join(msg_lines).strip()
    return patch_name, author_name, author_email, author_date, message

def make_patch_template(patch_name='', author_name=None, author_email=None, 
                         author_date=None, message='', comments=None):
    """Create a patch template for editing"""
    if author_name is None:
        author_name = get_user_name()
    if author_email is None:
        author_email = get_user_email()
    if author_date is None:
        author_date = datetime.now(tz=timezone.utc)

    if isinstance(author_date, datetime):
        date_str = author_date.strftime('%Y-%m-%d %H:%M:%S %z')
    else:
        date_str = str(author_date)

    template_lines = [
        f"Patch:  {patch_name}",
        f"Author: {author_name} <{author_email}>",
        f"Date:   {date_str}",
        "",
        message,
        "",
    ]

    if comments is None:
        comments = [
            "Please enter the message for your patch. Lines starting with",
            "'#' will be ignored. An empty message aborts the new patch.",
            "The patch name and author information may also be modified.",
        ]

    for c in comments:
        template_lines.append(f"# {c}")

    return '\n'.join(template_lines)

def add_trailers(message, signoff=None, ack=None, review=None, 
                 name=None, email=None):
    """Add trailers to a commit message"""
    if name is None:
        name = get_user_name()
    if email is None:
        email = get_user_email()

    trailers = []
    if signoff is not None:
        if signoff == '':
            trailers.append(f"Signed-off-by: {name} <{email}>")
        else:
            trailers.append(f"Signed-off-by: {signoff}")
    if ack is not None:
        if ack == '':
            trailers.append(f"Acked-by: {name} <{email}>")
        else:
            trailers.append(f"Acked-by: {ack}")
    if review is not None:
        if review == '':
            trailers.append(f"Reviewed-by: {name} <{email}>")
        else:
            trailers.append(f"Reviewed-by: {review}")

    if trailers:
        message = message.rstrip('\n')
        if message and not message.endswith('\n\n'):
            message += '\n'
        message += '\n'.join(trailers)

    return message


