        elif arg.startswith('-C') and len(arg) > 2:
            # -C/path/to/dir
            _C_args += ['-C', arg[2:]]
        else:
            remaining.append(arg)
            # Stop consuming global options once we hit a non-option or subcommand
            if not arg.startswith('-'):
                remaining += args[i+1:]
                break
        i += 1

    _setup_color(color_when)

    if not remaining:
        cmd_help_main()
        return

    cmd = remaining[0]
    cmd_args = remaining[1:]

    # Command dispatch
    dispatch = {
        'version': cmd_version,
        'help': cmd_help,
        'init': cmd_init,
        'series': cmd_series,
        'new': cmd_new,
        'push': cmd_push,
        'pop': cmd_pop,
        'show': cmd_show,
        'diff': cmd_diff,
        'files': cmd_files,
        'log': cmd_log,
        'id': cmd_id,
        'name': cmd_name,
        'top': cmd_top,
        'next': cmd_next,
        'prev': cmd_prev,
        'edit': cmd_edit,
        'refresh': cmd_refresh,
        'rename': cmd_rename,
        'delete': cmd_delete,
        'clean': cmd_clean,
        'branch': cmd_branch,
        'commit': cmd_commit,
        'uncommit': cmd_uncommit,
        'goto': cmd_goto,
