    return result.stdout.decode().strip()

def make_commit(tree, parents, author_name, author_email, author_date,
                committer_name, committer_email, committer_date, message):
    """Create a commit object"""
    if isinstance(author_date, datetime):
        author_date_str = format_git_date(author_date)
    else:
        author_date_str = str(author_date)

    if isinstance(committer_date, datetime):
        committer_date_str = format_git_date(committer_date)
    else:
        committer_date_str = str(committer_date)

    env = {
        'GIT_AUTHOR_NAME': author_name,
        'GIT_AUTHOR_EMAIL': author_email,
        'GIT_AUTHOR_DATE': author_date_str,
        'GIT_COMMITTER_NAME': committer_name,
        'GIT_COMMITTER_EMAIL': committer_email,
        'GIT_COMMITTER_DATE': committer_date_str,
    }

    cmd = ['commit-tree', tree]
    for p in parents:
        cmd += ['-p', p]
    cmd += ['-m', message]

    result = git(*cmd, env=env)
