def format_git_date(dt):
    """Format a datetime as git date string"""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    ts = int(dt.timestamp())
    offset = dt.utcoffset()
    if offset is None:
        offset_str = '+0000'
    else:
        total_seconds = int(offset.total_seconds())
        sign = '+' if total_seconds >= 0 else '-'
        total_seconds = abs(total_seconds)
        h = total_seconds // 3600
        m = (total_seconds % 3600) // 60
        offset_str = f'{sign}{h:02d}{m:02d}'
    return f'{ts} {offset_str}'

def parse_git_date(s):
    """Parse a git timestamp like '1234567890 +0200' to datetime"""
    parts = s.strip().split()
    ts = int(parts[0])
    if len(parts) > 1:
        tz_str = parts[1]
        sign = 1 if tz_str[0] == '+' else -1
        h = int(tz_str[1:3])
        m = int(tz_str[3:5])
        tz = timezone(timedelta(hours=sign*h, minutes=sign*m))
    else:
        tz = timezone.utc
    return datetime.fromtimestamp(ts, tz=tz)

