def get_stack(branch=None):
    """Get Stack object for a branch"""
    if branch is None:
        branch = get_current_branch()
        if branch is None:
            raise StgError("not on a branch")
    return Stack(branch)

def resolve_patch_or_rev(stack, spec):
    """Resolve a patch spec or git revision to a commit hash"""
    state = stack.get_state()

    # Handle patch^
    if spec.endswith('^'):
        patch_name = spec[:-1]
        if state.patch_exists(patch_name):
            oid = state.patches[patch_name]
            info = get_commit_info(oid)
            return info['parents'][0] if info.get('parents') else None

    # Handle {base}
    if spec == '{base}':
        return state.get_base()

    # Handle branch:patch or branch:{base}
    m = re.match(r'^([^:]+):(.+)$', spec)
    if m:
        b_branch = m.group(1)
        b_patch = m.group(2)
        other_stack = Stack(b_branch)
        return resolve_patch_or_rev(other_stack, b_patch)

    # Check if it's a patch name
    if state.patch_exists(spec):
        return state.patches[spec]

    # Try as git revision
    result = resolve_ref(spec)
    return result

def make_new_patch_commit(parent_commit, tree, author_name, author_email, author_date, 
                           committer_name, committer_email, committer_date, message):
    """Create a new patch commit"""
    return make_commit(
        tree, [parent_commit],
        author_name, author_email, author_date,
        committer_name, committer_email, committer_date,
        message
    )

def get_empty_tree():
    """Get the empty tree hash"""
    return git_output('hash-object', '-w', '-t', 'tree', '--stdin', input='')

def merge_trees(base_tree, head_tree, merge_tree, work_tree=None):
    """Merge two trees against a base"""
    # Use git merge-tree
    result = git('merge-tree', base_tree, head_tree, merge_tree, check=False)
    return result.stdout.decode(), result.returncode == 0

def checkout_tree(tree):
    """Checkout a tree to the working directory"""
    git('read-tree', '-u', '-m', tree)

def checkout_tree_from_to(from_tree, to_tree):
    """Checkout from one tree to another"""
    git('read-tree', '-u', '-m', from_tree, to_tree)

def get_index_tree():
    """Get the current index tree"""
    return git_output('write-tree')

def write_index_from_tree(tree):
    """Read a tree into the index"""
    git('read-tree', tree)

def is_work_tree_clean():
    """Check if work tree is clean (no unstaged changes)"""
    result = git('diff-files', '--quiet', check=False)
    return result.returncode == 0

def is_index_clean():
    """Check if index is clean (no staged changes)"""
    try:
        head = get_head()
        result = git('diff-index', '--quiet', '--cached', head, check=False)
        return result.returncode == 0
    except Exception:
        return True

def has_staged_changes():
    """Check if there are staged changes"""
    try:
        head = get_head()
        result = git('diff-index', '--quiet', '--cached', head, check=False)
        return result.returncode != 0
    except Exception:
        return False

def has_unstaged_changes():
    """Check if there are unstaged changes"""
    result = git('diff-files', '--quiet', check=False)
    return result.returncode != 0

def apply_patch_to_tree(patch_tree, base_tree, current_tree):
    """Apply a patch (from base_tree to patch_tree) onto current_tree"""
    # This is a 3-way merge: base=base_tree, ours=current_tree, theirs=patch_tree
    result = git('merge-tree', base_tree, current_tree, patch_tree, check=False)
    output = result.stdout.decode()

    if result.returncode != 0:
        return None, False, output

    # Parse merge-tree output
    # First line is the resulting tree
    lines = output.strip().split('\n') if output.strip() else []
    if lines:
        new_tree = lines[0]
        has_conflicts = len(lines) > 1
        return new_tree, not has_conflicts, output
    return None, False, output

