# ============================================================
# Git operations
# ============================================================

_C_args = []  # -C path args

def git(*args, input=None, check=True, capture=True, env=None):
    """Run a git command"""
    cmd = ['git'] + list(_C_args) + list(args)
    kwargs = {}
    if capture:
        kwargs['stdout'] = subprocess.PIPE
        kwargs['stderr'] = subprocess.PIPE
    if input is not None:
        kwargs['input'] = input if isinstance(input, bytes) else input.encode()

    if env is not None:
        kwargs['env'] = {**os.environ, **env}

    result = subprocess.run(cmd, **kwargs)
    if check and result.returncode != 0:
        stderr = result.stderr.decode() if capture and result.stderr else ''
        raise GitError(f"git {' '.join(args)} failed: {stderr.strip()}")
    return result

def git_output(*args, **kwargs):
    """Run git and return stdout as string"""
    result = git(*args, **kwargs)
    return result.stdout.decode().rstrip('\n')

def git_lines(*args, **kwargs):
    """Run git and return list of lines"""
    output = git_output(*args, **kwargs)
    if not output:
        return []
    return output.split('\n')

def git_bool(*args, **kwargs):
    """Run git and return True/False based on exit code"""
    result = git(*args, check=False, **kwargs)
    return result.returncode == 0

class GitError(Exception):
    pass

class StgError(Exception):
    def __init__(self, msg, code=2):
        super().__init__(msg)
        self.code = code

def get_git_dir():
    """Get the git directory"""
    try:
        return git_output('rev-parse', '--git-dir')
    except GitError:
        raise StgError("not a git repository")

def get_work_tree():
    """Get the work tree"""
    try:
        return git_output('rev-parse', '--show-toplevel')
    except GitError:
        return None

def resolve_ref(ref):
    """Resolve a ref to a hash"""
    try:
        return git_output('rev-parse', '--verify', ref)
    except GitError:
        return None

def ref_exists(ref):
    """Check if a ref exists"""
    return resolve_ref(ref) is not None

def get_head():
    """Get HEAD hash"""
    return resolve_ref('HEAD')

def get_current_branch():
    """Get current branch name"""
    try:
        symbolic = git_output('symbolic-ref', 'HEAD')
        if symbolic.startswith('refs/heads/'):
            return symbolic[len('refs/heads/'):]
        return None
    except GitError:
        return None

def get_branches():
    """Get all local branches"""
    try:
        lines = git_lines('for-each-ref', '--format=%(refname:short)', 'refs/heads/')
        return [l for l in lines if l]
    except GitError:
        return []

def hash_object(data, obj_type='blob'):
    """Hash an object and write it to the object store"""
    if isinstance(data, str):
        data = data.encode()
    result = git('hash-object', '-w', '-t', obj_type, '--stdin', input=data)
    return result.stdout.decode().strip()

def make_tree(entries):
    """Create a tree object from a list of (mode, type, hash, name) tuples"""
    # entries: list of (mode, type, oid, name)
    lines = []
    for mode, typ, oid, name in entries:
        lines.append(f'{mode} {typ} {oid}\t{name}')
    content = '\n'.join(lines) + '\n'
    result = git('mktree', input=content)
    return result.stdout.decode().strip()

def make_commit(tree, parents, author_name, author_email, author_date,
                committer_name, committer_email, committer_date, message):
    """Create a commit object"""
    if isinstance(author_date, datetime):
        author_date_str = format_git_date(author_date)
    else:
        author_date_str = str(author_date)

    if isinstance(committer_date, datetime):
        committer_date_str = format_git_date(committer_date)
    else:
        committer_date_str = str(committer_date)

    env = {
        'GIT_AUTHOR_NAME': author_name,
        'GIT_AUTHOR_EMAIL': author_email,
        'GIT_AUTHOR_DATE': author_date_str,
        'GIT_COMMITTER_NAME': committer_name,
        'GIT_COMMITTER_EMAIL': committer_email,
        'GIT_COMMITTER_DATE': committer_date_str,
    }

    cmd = ['commit-tree', tree]
    for p in parents:
        cmd += ['-p', p]
    cmd += ['-m', message]

    result = git(*cmd, env=env)
    return result.stdout.decode().strip()

def format_git_date(dt):
    """Format a datetime as git date string"""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    ts = int(dt.timestamp())
    offset = dt.utcoffset()
    if offset is None:
        offset_str = '+0000'
    else:
        total_seconds = int(offset.total_seconds())
        sign = '+' if total_seconds >= 0 else '-'
        total_seconds = abs(total_seconds)
        h = total_seconds // 3600
        m = (total_seconds % 3600) // 60
        offset_str = f'{sign}{h:02d}{m:02d}'
    return f'{ts} {offset_str}'

def parse_git_date(s):
    """Parse a git timestamp like '1234567890 +0200' to datetime"""
    parts = s.strip().split()
    ts = int(parts[0])
    if len(parts) > 1:
        tz_str = parts[1]
        sign = 1 if tz_str[0] == '+' else -1
        h = int(tz_str[1:3])
        m = int(tz_str[3:5])
        tz = timezone(timedelta(hours=sign*h, minutes=sign*m))
    else:
        tz = timezone.utc
    return datetime.fromtimestamp(ts, tz=tz)

def get_cat_file(oid, kind=None):
    """Get the content of a git object"""
    if kind:
        return git_output('cat-file', kind, oid)
    else:
        result = git('cat-file', '-p', oid)
        return result.stdout.decode()

def read_tree_to_index(tree):
    """Read a tree into the index"""
    git('read-tree', tree)

def update_ref(ref, new_hash, old_hash=None):
    """Update a ref"""
    cmd = ['update-ref', ref, new_hash]
    if old_hash:
        cmd.append(old_hash)
    git(*cmd)

def delete_ref(ref):
    """Delete a ref"""
    git('update-ref', '-d', ref)

def get_config(key):
    """Get a git config value"""
    try:
        return git_output('config', '--local', key)
    except GitError:
        return None

def set_config(key, value):
    """Set a git config value"""
    git('config', '--local', key, value)

def unset_config(key):
    """Unset a git config value"""
    git('config', '--local', '--unset', key, check=False)

def get_user_name():
    """Get user name from git config"""
    try:
        return git_output('config', 'user.name')
    except GitError:
        return os.environ.get('GIT_COMMITTER_NAME', os.environ.get('USER', 'Unknown'))

def get_user_email():
    """Get user email from git config"""
    try:
        return git_output('config', 'user.email')
    except GitError:
        return os.environ.get('GIT_COMMITTER_EMAIL', 'unknown@unknown')

def get_commit_info(oid):
    """Get commit information"""
    result = git('cat-file', '-p', oid)
    content = result.stdout.decode()
    lines = content.split('\n')
    info = {}
    i = 0
    while i < len(lines) and lines[i]:
        line = lines[i]
        if line.startswith('tree '):
            info['tree'] = line[5:]
        elif line.startswith('parent '):
            info.setdefault('parents', []).append(line[7:])
        elif line.startswith('author '):
            info['author'] = parse_identity_line(line[7:])
        elif line.startswith('committer '):
            info['committer'] = parse_identity_line(line[10:])
        i += 1
    # Rest is message
    message = '\n'.join(lines[i+1:])
    info['message'] = message
    return info

def parse_identity_line(line):
    """Parse 'Name <email> timestamp tzoffset' """
    # e.g., "John Doe <john@doe.com> 1234567890 +0000"
    m = re.match(r'^(.*?)\s+<([^>]*)>\s+(\d+\s+[+-]\d{4})$', line)
    if m:
        return {
            'name': m.group(1),
            'email': m.group(2),
            'date': parse_git_date(m.group(3)),
        }
    # Fallback
    m = re.match(r'^(.*?)\s+<([^>]*)>\s+(\d+)$', line)
    if m:
        return {
            'name': m.group(1),
            'email': m.group(2),
            'date': parse_git_date(m.group(3)),
        }
    return {'name': line, 'email': '', 'date': datetime.now(tz=timezone.utc)}

def get_tree_entries(tree_oid):
    """Get tree entries as list of (mode, type, oid, name)"""
    try:
        result = git('ls-tree', tree_oid)
        entries = []
        for line in result.stdout.decode().split('\n'):
            if not line:
                continue
            # format: "100644 blob abc123\tfilename"
            parts = line.split('\t', 1)
            if len(parts) != 2:
                continue
            meta, name = parts
            meta_parts = meta.split()
            if len(meta_parts) == 3:
                mode, typ, oid = meta_parts
                entries.append((mode, typ, oid, name))
        return entries
    except GitError:
        return []

def apply_diff(diff_text, base=None, strip=1, context=None, reject=False, threeway=False):
    """Apply a diff using git apply"""
    cmd = ['apply']
    if strip is not None and strip != 1:
        cmd += [f'-p{strip}']
    if context is not None:
        cmd += [f'-C{context}']
    if reject:
        cmd += ['--reject']
    if threeway:
        cmd += ['--3way']
    cmd += ['-']
    result = git(*cmd, input=diff_text, check=False)
    return result.returncode == 0, result.stderr.decode()

def merge_recursive(base, head, merge):
    """Perform a 3-way merge"""
    result = git('merge-recursive', base, '--', head, merge, check=False)
    return result.returncode == 0

