def main():
    global _C_args

    args = sys.argv[1:]

    # Process global options
    color_when = 'auto'
    remaining = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--version':
            cmd_version([])
            return
        elif arg in ('-h', '--help'):
            cmd_help_main()
            return
        elif arg == '--color':
            i += 1
            if i < len(args):
                color_when = args[i]
        elif arg.startswith('--color='):
            color_when = arg[8:]
        elif arg == '-C':
            i += 1
            if i < len(args):
                _C_args += ['-C', args[i]]
        elif arg.startswith('-C') and len(arg) > 2:
            # -C/path/to/dir
            _C_args += ['-C', arg[2:]]
        else:
            remaining.append(arg)
            # Stop consuming global options once we hit a non-option or subcommand
            if not arg.startswith('-'):
                remaining += args[i+1:]
                break
        i += 1

    _setup_color(color_when)

    if not remaining:
        cmd_help_main()
        return

    cmd = remaining[0]
    cmd_args = remaining[1:]

    # Command dispatch
    dispatch = {
        'version': cmd_version,
        'help': cmd_help,
        'init': cmd_init,
        'series': cmd_series,
        'new': cmd_new,
        'push': cmd_push,
        'pop': cmd_pop,
        'show': cmd_show,
        'diff': cmd_diff,
        'files': cmd_files,
        'log': cmd_log,
        'id': cmd_id,
        'name': cmd_name,
        'top': cmd_top,
        'next': cmd_next,
        'prev': cmd_prev,
        'edit': cmd_edit,
        'refresh': cmd_refresh,
        'rename': cmd_rename,
        'delete': cmd_delete,
        'clean': cmd_clean,
        'branch': cmd_branch,
        'commit': cmd_commit,
        'uncommit': cmd_uncommit,
        'goto': cmd_goto,
        'hide': cmd_hide,
        'unhide': cmd_unhide,
        'squash': cmd_squash,
        'sink': cmd_sink,
        'float': cmd_float,
        'pick': cmd_pick,
        'fold': cmd_fold,
        'sync': cmd_sync,
        'import': cmd_import,
        'export': cmd_export,
        'pull': cmd_pull,
        'rebase': cmd_rebase,
        'repair': cmd_repair,
        'reset': cmd_reset,
        'undo': cmd_undo,
        'redo': cmd_redo,
        'spill': cmd_spill,
        'patches': cmd_patches,
        'email': cmd_email,
        'completion': cmd_completion,
        # Aliases
        'add': cmd_alias_add,
        'mv': cmd_alias_mv,
        'resolved': cmd_alias_resolved,
        'rm': cmd_alias_rm,
        'status': cmd_alias_status,
    }

    if cmd not in dispatch:
        print(f"error: unknown command `{cmd}`", file=sys.stderr)
        sys.exit(2)

    try:
        dispatch[cmd](cmd_args)
    except StgError as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(e.code)
    except GitError as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(2)
    except KeyboardInterrupt:
        sys.exit(1)


