def parse_args(args, flags=None, options=None, positional=None):
    """
    Simple argument parser.
    flags: set of flag names (--flag) that take no value -> dict: name -> bool
    options: set of option names that take a value -> dict: name -> value
    Returns: (flags_dict, opts_dict, positional_list)
    """
    if flags is None:
        flags = set()
    if options is None:
        options = {}

    flags_result = {f: False for f in flags}
    opts_result = dict(options)  # defaults
    pos_result = []

    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--':
            pos_result += args[i+1:]
            break
        elif arg.startswith('--'):
            # Long option
            if '=' in arg:
                key, val = arg[2:].split('=', 1)
                option_key = f'--{key}'
                if option_key in options or option_key in {f'--{k}' for k in options}:
                    opts_result[key] = val
                elif option_key in flags or option_key in {f'--{k}' for k in flags}:
                    flags_result[key] = True  # with =value, ignore value
                else:
                    pos_result.append(arg)
            else:
                key = arg[2:]
                if arg in flags:
                    flags_result[key] = True
                elif arg in options:
                    i += 1
                    if i < len(args):
                        opts_result[key] = args[i]
                else:
                    pos_result.append(arg)
        elif arg.startswith('-') and len(arg) > 1 and not arg[1:].isdigit():
            # Short option - handle letter by letter
            j = 1
            while j < len(arg):
                c = arg[j]
                short_flag = f'-{c}'
                if short_flag in flags:
                    flags_result[c] = True
                    j += 1
                elif short_flag in options:
                    # Value is rest of arg or next arg
                    if j + 1 < len(arg):
                        opts_result[c] = arg[j+1:]
                        j = len(arg)
                    else:
                        i += 1
                        if i < len(args):
                            opts_result[c] = args[i]
                        j += 1
                else:
                    pos_result.append(arg[j-1:] if j > 1 else arg)
                    j += 1
        else:
            pos_result.append(arg)
        i += 1

    return flags_result, opts_result, pos_result


def get_branch_opt(args):
    """Extract -b/--branch option from args"""
    branch = None
    remaining = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-b', '--branch'):
            i += 1
            if i < len(args):
                branch = args[i]
        elif arg.startswith('--branch='):
            branch = arg[9:]
        elif arg.startswith('-b') and len(arg) > 2:
            branch = arg[2:]
        else:
            remaining.append(arg)
        i += 1
    return branch, remaining

def get_color_opt(args):
    """Extract --color option and return remaining args"""
    color = None
    remaining = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--color':
            i += 1
            if i < len(args):
                color = args[i]
        elif arg.startswith('--color='):
            color = arg[8:]
        else:
            remaining.append(arg)
        i += 1
    if color:
        _setup_color(color)
    return remaining


