        i += 1

    return flags_result, opts_result, pos_result


def get_branch_opt(args):
    """Extract -b/--branch option from args"""
    branch = None
    remaining = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-b', '--branch'):
            i += 1
            if i < len(args):
                branch = args[i]
        elif arg.startswith('--branch='):
            branch = arg[9:]
        elif arg.startswith('-b') and len(arg) > 2:
            branch = arg[2:]
        else:
            remaining.append(arg)
        i += 1
    return branch, remaining

def get_color_opt(args):
    """Extract --color option and return remaining args"""
    color = None
    remaining = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--color':
            i += 1
            if i < len(args):
                color = args[i]
        elif arg.startswith('--color='):
            color = arg[8:]
        else:
            remaining.append(arg)
        i += 1
    if color:
        _setup_color(color)
    return remaining


# ============================================================
# Command: init
# ============================================================

def cmd_init(args):
    args = get_color_opt(args)

    if '--help' in args or '-h' in args:
        print_init_help()
        return

    branch, args = get_branch_opt(args)

    if branch is None:
        branch = get_current_branch()
        if branch is None:
            raise StgError("not on a branch")

    stack = Stack(branch)
    if stack.is_initialized():
        raise StgError(f"stack already initialized for branch `{branch}`")

    # Verify branch exists
    branch_ref = f'refs/heads/{branch}'
    head_commit = resolve_ref(branch_ref)
    if head_commit is None:
        raise StgError(f"branch `{branch}` does not exist")

    stack.initialize(head_commit)

def print_init_help():
    print("""Initialize a StGit stack on a branch.

Initializing a branch with a StGit stack commits initial, empty stack state for the
branch to the repository. Theses stack metadata commits are tracked by the
`refs/stacks/<branch>` reference. Updated stack state is committed by each StGit command
that modifies the stack. StGit users do not have to do anything with the
`refs/stacks/<branch>` ref directly.

Some StGit commands, such as `stg new` and `stg uncommit`, will automatically initialize
the stack, so it is often not necessary to explicitly initialize the stack on a branch.
Also, branches created with `stg branch --create` are automatically initialized.

The branch must already exist and point to a commit before initializing a StGit stack.

StGit stack metadata can be deinitialized from a branch using `stg branch --cleanup`.
See 'stg branch' for more details.

Usage: stg init [OPTIONS]

Options:
  -b, --branch <branch>
          Use <branch> instead of current branch

      --color <when>
          Specify when to colorize the output.

  -h, --help
          Print help (see a summary with '-h')""")


# ============================================================
# Command: series  
# ============================================================

def cmd_series(args):
    args = get_color_opt(args)

    if '--help' in args or '-h' in args:
        print_series_help()
        return

    # Parse options
    branch = None
    select_all = False
    select_short = None  # None or integer
    select_applied = False
    select_unapplied = False
    select_hidden = False
    missing_branch = None
    show_author = False
    show_count = False
    show_commit_id = None  # None, True (full), or int (length)
    show_description = False
    no_description = False
    show_empty = False
    no_prefix = False
    show_indices = False
    show_offsets = False
    reverse_order = False
    show_branch = False
    patch_specs = []

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-b', '--branch'):
            i += 1
            if i < len(args):
                branch = args[i]
        elif arg.startswith('--branch='):
            branch = arg[9:]
        elif arg.startswith('-b') and len(arg) > 2:
            branch = arg[2:]
        elif arg in ('-a', '--all'):
            select_all = True
        elif arg in ('-s', '--short'):
            select_short = 5  # default
        elif arg.startswith('--short='):
            select_short = int(arg[8:])
        elif arg in ('-A', '--applied'):
            select_applied = True
        elif arg in ('-U', '--unapplied'):
            select_unapplied = True
        elif arg in ('-H', '--hidden'):
            select_hidden = True
        elif arg in ('-m', '--missing'):
            i += 1
            if i < len(args):
                missing_branch = args[i]
        elif arg.startswith('--missing='):
            missing_branch = arg[10:]
        elif arg == '--author':
            show_author = True
        elif arg in ('-c', '--count'):
            show_count = True
        elif arg in ('-i', '--commit-id'):
            show_commit_id = True  # full
        elif arg.startswith('--commit-id='):
            val = arg[12:]
            if val == 'full' or val == '':
                show_commit_id = True
            else:
                try:
                    show_commit_id = int(val)
                except ValueError:
                    show_commit_id = True
        elif arg in ('-d', '--description'):
            show_description = True
        elif arg == '--no-description':
            no_description = True
        elif arg in ('-e', '--empty'):
            show_empty = True
        elif arg in ('-P', '--no-prefix'):
            no_prefix = True
        elif arg in ('-I', '--indices'):
            show_indices = True
        elif arg in ('-O', '--offsets'):
            show_offsets = True
        elif arg in ('-r', '--reverse'):
            reverse_order = True
        elif arg == '--showbranch':
            show_branch = True
        elif arg.startswith('-'):
            raise StgError(f"unknown option `{arg}`")
        else:
            patch_specs.append(arg)
        i += 1

    if no_description:
        show_description = False

    if branch is None:
        branch = get_current_branch()
        if branch is None:
            raise StgError("not on a branch")

    stack = Stack(branch)
    if not stack.is_initialized():
        # Auto-init? No, just raise error
        raise StgError(f"branch `{branch}` is not initialized")

    state = stack.get_state()

    # Build the list of patches to display
    if missing_branch:
        # Show patches in current branch not in missing_branch
        other_stack = Stack(missing_branch)
        other_state = other_stack.get_state()
        other_patches = set(other_state.all_patch_names())

        all_current = []
        if select_applied or (not select_applied and not select_unapplied and not select_hidden and not select_all):
            all_current += [(p, '>+') for p in state.applied]
        if select_unapplied or select_all or (not select_applied and not select_unapplied and not select_hidden and not select_all):
            all_current += [(p, '-') for p in state.unapplied]
        if select_hidden or select_all:
            all_current += [(p, '!') for p in state.hidden]

        patches_to_show = [(p, s) for p, s in all_current if p not in other_patches]

        # Resolve statuses
        top = state.top_patch()
        result_patches = []
        for p, s in patches_to_show:
            if s == '>+':
                if p == top:
                    result_patches.append((p, '>'))
                else:
                    result_patches.append((p, '+'))
            else:
                result_patches.append((p, s))
    elif patch_specs:
        # Show specific patches
        result_patches = []
        top = state.top_patch()
        for spec in patch_specs:
            # Could be a range like p1..p2
            if '..' in spec:
                parts = spec.split('..', 1)
                p1, p2 = parts
                all_names = state.applied + state.unapplied + state.hidden
                try:
                    i1 = all_names.index(p1)
                    i2 = all_names.index(p2)
                    if i1 > i2:
                        i1, i2 = i2, i1
                    for p in all_names[i1:i2+1]:
                        if state.is_applied(p):
                            status = '>' if p == top else '+'
                        elif state.is_unapplied(p):
                            status = '-'
                        else:
                            status = '!'
                        result_patches.append((p, status))
                except ValueError:
                    raise StgError(f"patch `{spec}` does not exist")
            else:
                if not state.patch_exists(spec):
                    raise StgError(f"patch `{spec}` does not exist")
                if state.is_applied(spec):
                    status = '>' if spec == top else '+'
                elif state.is_unapplied(spec):
                    status = '-'
                else:
                    status = '!'
                result_patches.append((spec, status))
    else:
        # Default: show based on select options
        patches_with_status = []
        top = state.top_patch()

        show_app = select_applied or (not select_applied and not select_unapplied and not select_hidden and not select_all)
        show_unapp = select_unapplied or (not select_applied and not select_unapplied and not select_hidden and not select_all)
        show_hid = select_hidden or select_all
        show_app = show_app or select_all
        show_unapp = show_unapp or select_all

        if show_app:
            for p in state.applied:
                status = '>' if p == top else '+'
                patches_with_status.append((p, status))
        if show_unapp:
            for p in state.unapplied:
                patches_with_status.append((p, '-'))
        if show_hid:
            for p in state.hidden:
                patches_with_status.append((p, '!'))

        result_patches = patches_with_status

        # Handle --short
        if select_short is not None:
            top_idx = None
            for idx, (p, s) in enumerate(result_patches):
                if s == '>':
                    top_idx = idx
                    break

            if top_idx is None:
                # No applied patches: show first N unapplied
                result_patches = result_patches[:select_short]
            else:
                start = max(0, top_idx - select_short + 1)
                end = min(len(result_patches), top_idx + select_short)
                result_patches = result_patches[start:end]

    if show_count:
        print(len(result_patches))
        return

    if reverse_order:
        result_patches = list(reversed(result_patches))

    # Format and print
    all_patches_for_index = state.applied + state.unapplied + state.hidden
    top = state.top_patch()
    top_idx = len(state.applied) - 1 if state.applied else -1

    # For description padding
    max_name_len = max((len(p) for p, s in result_patches), default=0)
    if show_description:
        max_name_len = max(max_name_len, 1)

    for idx, (pname, status) in enumerate(result_patches):
        # Build prefix parts
        parts = []

        # Empty column
        if show_empty:
            oid = state.patches.get(pname)
            is_empty = False
            if oid:
                try:
                    commit_info = get_commit_info(oid)
                    patch_tree = commit_info['tree']
                    parent_oid = commit_info['parents'][0] if commit_info.get('parents') else None
                    if parent_oid:
                        parent_info = get_commit_info(parent_oid)
                        parent_tree = parent_info['tree']
                        is_empty = (patch_tree == parent_tree)
                    else:
                        is_empty = True
                except Exception:
                    pass
            parts.append('*' if is_empty else ' ')

        # Status prefix
        if not no_prefix:
            status_char = status
            if _color_enabled:
                if status == '+':
                    colored_status = colorize(status, Color.GREEN)
                elif status == '>':
                    colored_status = colorize(status, Color.BLUE)
                elif status == '-':
                    colored_status = colorize(status, Color.MAGENTA)
                elif status == '!':
                    colored_status = colorize(status, Color.RED)
                else:
                    colored_status = status
                parts.append(colored_status + ' ')
            else:
                parts.append(status + ' ')

        # Commit ID
        if show_commit_id is not None:
            oid = state.patches.get(pname, '')
            if show_commit_id is True:
                parts.append(oid + ' ')
            elif isinstance(show_commit_id, int):
                parts.append(oid[:show_commit_id] + ' ')

        # Indices
        if show_indices:
            patch_idx = all_patches_for_index.index(pname) if pname in all_patches_for_index else idx
            parts.append(f"{patch_idx} ")

        # Offsets
        if show_offsets:
            patch_idx = all_patches_for_index.index(pname) if pname in all_patches_for_index else idx
            offset = patch_idx - top_idx
            if offset > 0:
                parts.append(f"+{offset} ")
            else:
                parts.append(f"{offset} ")

        # Patch name
        if show_branch:
            display_name = f"{branch}:{pname}"
        else:
            display_name = pname

        if _color_enabled:
            if status == '>':
                colored_name = colorize(display_name, Color.BOLD)
            elif status in ('-',):
                colored_name = colorize(display_name, Color.DIM)
            elif status == '!':
                colored_name = colorize(display_name, Color.DIM, Color.ITALIC)
            else:
                colored_name = colorize(display_name)
            parts.append(colored_name)
        else:
            parts.append(display_name)

        # Description / author
        if show_description or show_author:
            # Pad the name
            if show_description and show_author:
                # show both?
                pass

            if show_description:
                # Get description (first line of commit message)
                oid = state.patches.get(pname)
                desc = ''
                if oid:
                    try:
                        commit_info = get_commit_info(oid)
                        msg = commit_info.get('message', '')
                        desc = msg.strip().split('\n')[0]
                    except Exception:
                        pass
                pad = ' ' * (max_name_len - len(display_name) + 1)
                parts.append(f"{pad}# {desc}")
            elif show_author:
                oid = state.patches.get(pname)
                author_name = ''
                if oid:
                    try:
                        commit_info = get_commit_info(oid)
                        author = commit_info.get('author', {})
                        author_name = author.get('name', '')
                    except Exception:
                        pass
                pad = ' ' * (max_name_len - len(display_name) + 1)
                parts.append(f"{pad}# {author_name}")

        print(''.join(parts))

def print_series_help():
    print("""Show all the patches in the series, or just those in the given range, ordered from
