def cmd_show(args):
    args = get_color_opt(args)

    if '--help' in args or '-h' in args:
        print("Show patch commits.")
        return

    branch = None
    patch_specs = []
    show_stat = False
    show_applied = False
    show_unapplied = False
    show_hidden = False
    diff_opts = []
    paths = []
    after_dashdash = False

    i = 0
    while i < len(args):
        arg = args[i]
        if after_dashdash:
            paths.append(arg)
        elif arg == '--':
            after_dashdash = True
        elif arg in ('-b', '--branch'):
            i += 1
            if i < len(args):
                branch = args[i]
        elif arg.startswith('--branch='):
            branch = arg[9:]
        elif arg in ('-s', '--stat'):
            show_stat = True
        elif arg in ('-p', '--patch'):
            i += 1
            if i < len(args):
                patch_specs.append(args[i])
        elif arg.startswith('--patch='):
            patch_specs.append(arg[8:])
        elif arg in ('-A', '--applied'):
            show_applied = True
        elif arg in ('-U', '--unapplied'):
            show_unapplied = True
        elif arg in ('-H', '--hidden'):
            show_hidden = True
        elif arg in ('-O', '--diff-opt'):
            i += 1
            if i < len(args):
                diff_opts.append(args[i])
        elif arg.startswith('--diff-opt='):
            diff_opts.append(arg[11:])
        elif arg.startswith('-'):
            raise StgError(f"unknown option `{arg}`")
        else:
            patch_specs.append(arg)
        i += 1

    if branch is None:
        branch = get_current_branch()
        if branch is None:
            raise StgError("not on a branch")

    stack = Stack(branch)
    if not stack.is_initialized():
        raise StgError(f"branch `{branch}` is not initialized")

    state = stack.get_state()

    # Determine patches to show
    if show_applied:
        patch_specs = list(state.applied)
    elif show_unapplied:
        patch_specs = list(state.unapplied)
    elif show_hidden:
        patch_specs = list(state.hidden)
    elif not patch_specs:
        # Default: show top patch or HEAD
        top = state.top_patch()
        if top:
            patch_specs = [top]
        else:
            # Show HEAD
            head = get_head()
            patch_specs = [head]

    for spec in patch_specs:
        # Resolve to commit hash
        if state.patch_exists(spec):
            oid = state.patches[spec]
        else:
            oid = resolve_ref(spec)
            if oid is None:
                raise StgError(f"patch or revision `{spec}` does not exist")

        cmd_args = ['show', '--format=commit %H%nAuthor: %an <%ae>%nDate:   %ad', '--date=local']
        if show_stat:
            cmd_args += ['--stat']
        else:
            cmd_args += ['--patch']
        cmd_args += diff_opts
        cmd_args += [oid]
        if paths:
            cmd_args += ['--'] + paths

        result = git('show', *cmd_args[1:], capture=False)


# ============================================================
# Command: diff  
# ============================================================

def cmd_diff(args):
    args = get_color_opt(args)

    if '--help' in args or '-h' in args:
        print("Show a diff.")
        return

    rev_range = None
    show_stat = False
    diff_opts = []
    paths = []

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-r', '--range'):
            i += 1
            if i < len(args):
                rev_range = args[i]
        elif arg.startswith('--range='):
            rev_range = arg[8:]
        elif arg in ('-s', '--stat'):
            show_stat = True
        elif arg in ('-O', '--diff-opt'):
            i += 1
            if i < len(args):
                diff_opts.append(args[i])
        elif arg.startswith('--diff-opt='):
            diff_opts.append(arg[11:])
        elif arg.startswith('-'):
            raise StgError(f"unknown option `{arg}`")
        else:
            paths.append(arg)
        i += 1

    branch = get_current_branch()
    stack = None
    if branch:
        stack = Stack(branch)
        if not stack.is_initialized():
            stack = None

    cmd_args = ['diff']
    if show_stat:
        cmd_args += ['--stat']
    cmd_args += diff_opts

    if rev_range:
        # Parse revspec
        if '..' in rev_range:
            parts = rev_range.split('..', 1)
            rev1, rev2 = parts

            def resolve_rev(spec):
                if stack and stack.get_state().patch_exists(spec):
                    return stack.get_state().patches[spec]
                if stack and spec == '{base}':
                    return stack.get_state().get_base()
                if stack and spec.endswith('^') and stack.get_state().patch_exists(spec[:-1]):
                    oid = stack.get_state().patches[spec[:-1]]
                    info = get_commit_info(oid)
                    return info['parents'][0] if info.get('parents') else None
                return spec

            r1 = resolve_rev(rev1) if rev1 else None
            r2 = resolve_rev(rev2) if rev2 else None

            if r1 and r2:
                cmd_args += [f'{r1}..{r2}']
            elif r1:
                cmd_args += [r1, 'HEAD']
            elif r2:
                cmd_args += [f'HEAD..{r2}']
        else:
            # Single revision: diff from that to HEAD
            if stack and stack.get_state().patch_exists(rev_range):
                rev = stack.get_state().patches[rev_range]
            else:
                rev = rev_range
            cmd_args += [rev, 'HEAD']
    else:
        # Default: diff from HEAD to working tree
        pass

    if paths:
        cmd_args += ['--'] + paths

    result = git(*cmd_args, capture=False)


# ============================================================
# Command: files
# ============================================================

def cmd_files(args):
    args = get_color_opt(args)

    if '--help' in args or '-h' in args:
        print("Show files modified by a patch.")
        return

    show_stat = False
    bare = False
    revision = None

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-s', '--stat'):
            show_stat = True
        elif arg == '--bare':
            bare = True
        elif arg.startswith('-'):
            raise StgError(f"unknown option `{arg}`")
        else:
            revision = arg
        i += 1

    branch = get_current_branch()
    if branch is None:
        raise StgError("not on a branch")

    stack = Stack(branch)
    if not stack.is_initialized():
        raise StgError(f"branch `{branch}` is not initialized")

    state = stack.get_state()

    if revision is None:
        top = state.top_patch()
        if top:
            oid = state.patches[top]
        else:
            raise StgError("no patches applied")
    elif state.patch_exists(revision):
        oid = state.patches[revision]
    else:
        oid = resolve_ref(revision)
        if oid is None:
            raise StgError(f"revision `{revision}` does not exist")

    commit_info = get_commit_info(oid)
    parent = commit_info['parents'][0] if commit_info.get('parents') else None

    if parent is None:
        cmd_args = ['diff-tree', '--no-commit-id', '-r', '--name-status', oid]
    else:
        cmd_args = ['diff-tree', '--no-commit-id', '-r', '--name-status', parent, oid]

    if show_stat:
        if parent:
            result = git('diff', '--stat', f'{parent}..{oid}', capture=False)
        else:
            result = git('diff', '--stat', oid, capture=False)
        return

    result = git(*cmd_args)
    lines = result.stdout.decode().split('\n')
    for line in lines:
        if not line:
            continue
        parts = line.split('\t', 1)
        if len(parts) == 2:
            status, fname = parts
            if bare:
                print(fname)
            else:
                print(f"{status} {fname}")


