def cmd_log(args):
    args = get_color_opt(args)

    if '--help' in args or '-h' in args:
        print("Display or optionally clear the stack changelog.")
        return

    branch = None
    show_diff = False
    number = None
    full_format = False
    graphical = False
    clear = False
    patch_specs = []

    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--':
            patch_specs += args[i+1:]
            break
        elif arg in ('-b', '--branch'):
            i += 1
            if i < len(args):
