def cmd_name(args):
    args = get_color_opt(args)

    if '--help' in args or '-h' in args:
        print("Print patch name of a StGit revision.")
        return

    branch = None
    show_branch_flag = False
    revision = None

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-b', '--branch'):
            i += 1
            if i < len(args):
                branch = args[i]
        elif arg.startswith('--branch='):
            branch = arg[9:]
        elif arg == '--showbranch':
            show_branch_flag = True
        elif arg.startswith('-'):
            raise StgError(f"unknown option `{arg}`")
        else:
            revision = arg
        i += 1

    if branch is None:
        branch = get_current_branch()
        if branch is None:
            raise StgError("not on a branch")

    stack = Stack(branch)
    if not stack.is_initialized():
        raise StgError(f"branch `{branch}` is not initialized")

    state = stack.get_state()

    # Resolve revision to hash
    if revision is None:
        # Default: top patch
        top = state.top_patch()
        if top:
            if show_branch_flag:
                print(f"{branch}:{top}")
            else:
                print(top)
            return
        raise StgError("no patches applied")

    # Try to resolve as a patch name first
    if state.patch_exists(revision):
        if show_branch_flag:
            print(f"{branch}:{revision}")
        else:
            print(revision)
        return

    # Resolve as git revision
    oid = resolve_ref(revision)
    if oid is None:
        raise StgError(f"revision `{revision}` does not exist")

    # Find which patch this corresponds to
    for pname, poid in state.patches.items():
        if poid == oid:
            if show_branch_flag:
                print(f"{branch}:{pname}")
            else:
                print(pname)
            return

    raise StgError(f"revision `{revision}` does not correspond to a patch")


