        elif arg in ('-U', '--unapplied'):
            delete_unapplied = True
        elif arg in ('-H', '--hidden'):
            delete_hidden = True
        elif arg in ('-t', '--top'):
            delete_top = True
        elif arg == '--spill':
            spill = True
        elif arg in ('-b', '--branch'):
            i += 1
            if i < len(args):
                branch = args[i]
        elif arg.startswith('--branch='):
            branch = arg[9:]
        elif arg.startswith('--conflicts'):
            pass
        elif arg.startswith('-'):
