        if top:
            to_delete = [top]
    else:
        to_delete = patch_names

    if not to_delete:
        raise StgError("no patches to delete")

    # Validate
    for pname in to_delete:
        if not state.patch_exists(pname):
            raise StgError(f"patch `{pname}` does not exist")

    now = datetime.now(tz=timezone.utc)

    # Handle spill (delete applied top patches without modifying work tree)
    if spill:
        # Only works for applied patches at top of stack
