def cmd_rename(args):
    args = get_color_opt(args)

    if '--help' in args or '-h' in args:
        print("Rename a patch.")
        return

    branch, args = get_branch_opt(args)

    positional = [a for a in args if not a.startswith('-')]

    if len(positional) < 1:
        raise StgError("missing patch name argument")
    elif len(positional) == 1:
        old_name = None
        new_name = positional[0]
    else:
        old_name = positional[0]
        new_name = positional[1]

    if branch is None:
        branch = get_current_branch()
        if branch is None:
            raise StgError("not on a branch")

    stack = Stack(branch)
    if not stack.is_initialized():
        raise StgError(f"branch `{branch}` is not initialized")

    state = stack.get_state()

    if old_name is None:
        old_name = state.top_patch()
        if old_name is None:
            raise StgError("no patches applied")

    if not state.patch_exists(old_name):
        raise StgError(f"patch `{old_name}` does not exist")

    if state.patch_exists(new_name):
        raise StgError(f"patch `{new_name}` already exists")

    validate_patch_name(new_name)

    # Rename in state
    oid = state.patches.pop(old_name)
    state.patches[new_name] = oid

    # Update lists
    for lst in [state.applied, state.unapplied, state.hidden]:
        if old_name in lst:
            idx = lst.index(old_name)
            lst[idx] = new_name
            break

    # Update descriptor cache
    if old_name in stack._patch_descs:
        stack._patch_descs[new_name] = stack._patch_descs.pop(old_name)

    print(f"{old_name} => {new_name}")

