def cmd_delete(args):
    args = get_color_opt(args)

    if '--help' in args or '-h' in args:
        print("Delete patches.")
        return

    delete_all = False
    delete_applied = False
    delete_unapplied = False
    delete_hidden = False
    delete_top = False
    spill = False
    branch = None
    patch_names = []

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-a', '--all'):
            delete_all = True
        elif arg in ('-A', '--applied'):
            delete_applied = True
        elif arg in ('-U', '--unapplied'):
            delete_unapplied = True
        elif arg in ('-H', '--hidden'):
            delete_hidden = True
        elif arg in ('-t', '--top'):
            delete_top = True
        elif arg == '--spill':
            spill = True
        elif arg in ('-b', '--branch'):
            i += 1
            if i < len(args):
                branch = args[i]
        elif arg.startswith('--branch='):
            branch = arg[9:]
        elif arg.startswith('--conflicts'):
            pass
        elif arg.startswith('-'):
            raise StgError(f"unknown option `{arg}`")
        else:
            patch_names.append(arg)
        i += 1

    if branch is None:
        branch = get_current_branch()
        if branch is None:
            raise StgError("not on a branch")

    stack = Stack(branch)
    if not stack.is_initialized():
        raise StgError(f"branch `{branch}` is not initialized")

    state = stack.get_state()

    # Determine which patches to delete
    to_delete = []

    if delete_all:
        to_delete = list(state.applied) + list(state.unapplied) + list(state.hidden)
    elif delete_applied:
        to_delete = list(state.applied)
    elif delete_unapplied:
        to_delete = list(state.unapplied)
    elif delete_hidden:
        to_delete = list(state.hidden)
    elif delete_top:
        top = state.top_patch()
        if top:
            to_delete = [top]
    else:
        to_delete = patch_names

    if not to_delete:
        raise StgError("no patches to delete")

    # Validate
    for pname in to_delete:
        if not state.patch_exists(pname):
            raise StgError(f"patch `{pname}` does not exist")

    now = datetime.now(tz=timezone.utc)

    # Handle spill (delete applied top patches without modifying work tree)
    if spill:
        # Only works for applied patches at top of stack
        for pname in to_delete:
            if not state.is_applied(pname):
                raise StgError(f"--spill can only be used with applied patches")

    # Need to pop applied patches that are being deleted
    applied_to_delete = [p for p in to_delete if state.is_applied(p)]

    if applied_to_delete:
        # Find the lowest one
        min_idx = min(state.applied.index(p) for p in applied_to_delete)

        # Need to pop everything from min_idx upward
        patches_to_pop = list(reversed(state.applied[min_idx:]))
        patches_to_keep_unapplied = [p for p in patches_to_pop if p not in to_delete]

        # Determine new head
        if min_idx > 0:
            new_head = state.patches[state.applied[min_idx - 1]]
        else:
            new_head = state.get_base()

        # Update state
        for p in patches_to_pop:
            state.applied.remove(p)

        state.head = new_head

        if not spill:
            # Update working tree
            try:
                new_head_info = get_commit_info(new_head)
                new_tree = new_head_info['tree']
                git('read-tree', '-u', '-m', 'HEAD', new_tree, check=False)
            except Exception:
                pass

        update_ref(f'refs/heads/{branch}', new_head)

        # Add non-deleted patches back as unapplied
        for p in patches_to_keep_unapplied:
            state.unapplied.insert(0, p)

    # Remove patches from state
    for pname in to_delete:
        if pname in state.unapplied:
            state.unapplied.remove(pname)
        elif pname in state.hidden:
            state.hidden.remove(pname)
        if pname in state.patches:
            del state.patches[pname]
        if pname in stack._patch_descs:
            del stack._patch_descs[pname]

    if len(to_delete) > 1:
        print(f"# {to_delete[0]}..{to_delete[-1]}")
    else:
        for p in to_delete:
            print(f"# {p}")

    stack.save_state(state, f"delete", now)


