# ============================================================
# Command: goto
# ============================================================

def cmd_goto(args):
    args = get_color_opt(args)

    if '--help' in args or '-h' in args:
        print("Go to patch by pushing or popping as necessary.")
        return

    keep = False
    merged = False
    committer_date_is_author = False
    target = None

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-k', '--keep'):
            keep = True
        elif arg in ('-m', '--merged'):
            merged = True
        elif arg == '--committer-date-is-author-date':
            committer_date_is_author = True
        elif arg.startswith('--conflicts'):
            pass
        elif arg.startswith('-'):
            raise StgError(f"unknown option `{arg}`")
        else:
            target = arg
        i += 1

    if target is None:
        raise StgError("missing patch name")

    branch = get_current_branch()
    if branch is None:
        raise StgError("not on a branch")

    stack = Stack(branch)
    if not stack.is_initialized():
        raise StgError(f"branch `{branch}` is not initialized")

    state = stack.get_state()

    if not state.patch_exists(target):
        raise StgError(f"patch `{target}` does not exist")

    now = datetime.now(tz=timezone.utc)

    # Determine current position and target position
    all_patches = state.applied + state.unapplied

    if state.is_applied(target):
        # Need to pop patches above it
        top = state.top_patch()
        if top == target:
            return  # Already there

        idx = state.applied.index(target)
        to_pop = list(reversed(state.applied[idx+1:]))

        # Pop them
        if len(to_pop) > 1:
            print(f"- {to_pop[-1]}..{to_pop[0]}")
        elif to_pop:
            for p in to_pop:
                print(f"- {p}")

        for p in to_pop:
            state.applied.remove(p)
            state.unapplied.insert(0, p)

        state.head = state.patches[target]

        if not keep:
            try:
                head_info = get_commit_info(state.head)
                git('read-tree', '-u', '-m', 'HEAD', head_info['tree'], check=False)
            except Exception:
                pass

        update_ref(f'refs/heads/{branch}', state.head)
        stack.save_state(state, f"goto", now)
        print(f"> {target}")

    elif state.is_unapplied(target):
        # Need to push patches up to and including target
        # Pop any hidden patches first? No, just push unapplied
        to_push = []
        for p in state.unapplied:
            to_push.append(p)
            if p == target:
                break

        for pname in to_push:
            if pname not in state.unapplied:
                continue

            old_oid = state.patches[pname]
            old_info = get_commit_info(old_oid)
            old_tree = old_info['tree']
            old_parent = old_info['parents'][0] if old_info.get('parents') else None

            current_head = state.head
            current_info = get_commit_info(current_head)
            current_tree = current_info['tree']

            author = old_info['author']

            if old_parent is None or old_parent == old_tree:
                new_tree = current_tree
            else:
                old_parent_info = get_commit_info(old_parent)
                old_parent_tree = old_parent_info['tree']

                if old_parent_tree == current_tree:
                    new_tree = old_tree
                elif old_parent_tree == old_tree:
                    new_tree = current_tree
                else:
                    result = git('merge-tree', '--write-tree', old_parent_tree, current_tree, old_tree, check=False)
                    new_tree = result.stdout.decode().strip().split('\n')[0].strip()
                    if not new_tree:
                        new_tree = current_tree

            new_oid = make_commit(
                new_tree, [current_head],
                author['name'], author['email'], author['date'],
                get_user_name(), get_user_email(), now,
                old_info['message']
            )

            state.unapplied.remove(pname)
            state.applied.append(pname)
            state.patches[pname] = new_oid
            state.head = new_oid

            parent_info = get_commit_info(current_head)
            desc = PatchDescriptor(
                bottom=current_tree,
                top=new_tree,
                author_name=author['name'],
                author_email=author['email'],
                author_date=author['date'],
                message=old_info['message']
            )
            stack._patch_descs[pname] = desc

            print(f"> {pname}")

        update_ref(f'refs/heads/{branch}', state.head)
        stack.save_state(state, f"goto", now)
    else:
        raise StgError(f"patch `{target}` is hidden")


# ============================================================
# Command: hide/unhide
# ============================================================

def cmd_hide(args):
    args = get_color_opt(args)

    if '--help' in args or '-h' in args:
        print("Hide patches in the series.")
        return

    branch, args = get_branch_opt(args)
    patch_names = [a for a in args if not a.startswith('-')]

    if not patch_names:
        raise StgError("no patches specified")

    if branch is None:
        branch = get_current_branch()
        if branch is None:
            raise StgError("not on a branch")

    stack = Stack(branch)
    if not stack.is_initialized():
        raise StgError(f"branch `{branch}` is not initialized")

    state = stack.get_state()
    now = datetime.now(tz=timezone.utc)

    for pname in patch_names:
        if not state.patch_exists(pname):
            raise StgError(f"patch `{pname}` does not exist")
        if state.is_hidden(pname):
            continue
        if state.is_applied(pname):
            # Need to pop it first
            idx = state.applied.index(pname)
            to_pop = list(reversed(state.applied[idx:]))

            if len(to_pop) > 1:
                print(f"- {to_pop[-1]}..{to_pop[0]}")
            else:
                for p in to_pop:
                    print(f"- {p}")

            # Get new head
            if idx > 0:
                new_head = state.patches[state.applied[idx - 1]]
            else:
                new_head = state.get_base()

            # Move applied patches to unapplied or hidden
            for p in to_pop:
                state.applied.remove(p)
                if p == pname:
                    state.hidden.append(p)
                else:
                    state.unapplied.insert(0, p)

            state.head = new_head

            try:
                head_info = get_commit_info(new_head)
                git('read-tree', '-u', '-m', 'HEAD', head_info['tree'], check=False)
            except Exception:
                pass

            update_ref(f'refs/heads/{branch}', new_head)
        elif state.is_unapplied(pname):
            state.unapplied.remove(pname)
            state.hidden.append(pname)

    stack.save_state(state, f"hide", now)

def cmd_unhide(args):
    args = get_color_opt(args)

    if '--help' in args or '-h' in args:
        print("Unhide hidden patches.")
        return

    branch, args = get_branch_opt(args)
    patch_names = [a for a in args if not a.startswith('-')]

    if not patch_names:
        raise StgError("no patches specified")

    if branch is None:
        branch = get_current_branch()
        if branch is None:
            raise StgError("not on a branch")

    stack = Stack(branch)
    if not stack.is_initialized():
        raise StgError(f"branch `{branch}` is not initialized")

    state = stack.get_state()
    now = datetime.now(tz=timezone.utc)

    for pname in patch_names:
        if not state.patch_exists(pname):
            raise StgError(f"patch `{pname}` does not exist")
        if not state.is_hidden(pname):
            raise StgError(f"patch `{pname}` is not hidden")
        state.hidden.remove(pname)
        state.unapplied.append(pname)

    stack.save_state(state, f"unhide", now)


