    )

    state.patches[top] = new_oid
    state.head = new_oid

    parent_info = get_commit_info(parent) if parent else None
    parent_tree = parent_info['tree'] if parent_info else new_tree

    desc = PatchDescriptor(
        bottom=parent_tree,
        top=new_tree,
        author_name=author['name'],
        author_email=author['email'],
        author_date=author['date'],
        message=info['message']
    )
    stack._patch_descs[top] = desc

    update_ref(f'refs/heads/{branch}', new_oid)
    stack.save_state(state, f"fold {top}", now)


def cmd_sync(args):
    args = get_color_opt(args)
    if '--help' in args or '-h' in args:
        print("Synchronize patches with a branch or a series.")
        return

    sync_all = False
    ref_branch = None
    series_file = None
    committer_date_is_author = False
    patch_names = []

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-a', '--all'):
            sync_all = True
        elif arg in ('-B', '--ref-branch'):
            i += 1
            if i < len(args):
                ref_branch = args[i]
        elif arg.startswith('--ref-branch='):
            ref_branch = arg[13:]
        elif arg in ('-S', '--series'):
            i += 1
            if i < len(args):
                series_file = args[i]
        elif arg.startswith('--series='):
            series_file = arg[9:]
        elif arg == '--committer-date-is-author-date':
            committer_date_is_author = True
        elif arg.startswith('-'):
            pass
        else:
            patch_names.append(arg)
        i += 1

    if not ref_branch and not series_file:
        raise StgError("must specify --ref-branch or --series")

    branch = get_current_branch()
    if branch is None:
        raise StgError("not on a branch")

    stack = Stack(branch)
    if not stack.is_initialized():
        raise StgError(f"branch `{branch}` is not initialized")

    state = stack.get_state()
    now = datetime.now(tz=timezone.utc)

    if sync_all:
        to_sync = list(state.applied)
    elif patch_names:
        to_sync = patch_names
    else:
        top = state.top_patch()
        if top:
            to_sync = [top]
        else:
            raise StgError("no patches to sync")

    # For each patch, do a 3-way merge with the same patch in ref_branch
    for pname in to_sync:
        if not state.is_applied(pname):
            continue

        if ref_branch:
            other_stack = Stack(ref_branch)
            other_state = other_stack.get_state()
            if not other_state.patch_exists(pname):
                continue
            other_oid = other_state.patches[pname]
        else:
            # Use series file
            continue

        oid = state.patches[pname]
        info = get_commit_info(oid)
        parent = info['parents'][0] if info.get('parents') else None

        other_info = get_commit_info(other_oid)
        other_parent = other_info['parents'][0] if other_info.get('parents') else None

        if other_parent is None:
            continue

        other_parent_info = get_commit_info(other_parent)
        other_parent_tree = other_parent_info['tree']

        # 3-way merge: base=other_parent, ours=info['tree'], theirs=other_info['tree']
        result = git('merge-tree', '--write-tree', other_parent_tree, info['tree'], other_info['tree'], check=False)
        new_tree = result.stdout.decode().strip().split('\n')[0].strip()
        if not new_tree:
            continue

        author = info['author']
        if committer_date_is_author:
            committer_date = author['date']
        else:
            committer_date = now

        new_oid = make_commit(
            new_tree, [parent] if parent else [],
            author['name'], author['email'], author['date'],
            get_user_name(), get_user_email(), committer_date,
            info['message']
        )

        state.patches[pname] = new_oid
        if pname == state.top_patch():
            state.head = new_oid
            update_ref(f'refs/heads/{branch}', new_oid)

        print(f"> {pname}")

    stack.save_state(state, "sync", now)


