def _import_patch_file(stack, state, file_path, name, strip, threeway, reject, ignore, replace, now):
    """Import a single patch file"""
    try:
        with open(file_path, 'r', errors='replace') as f:
            content = f.read()
    except FileNotFoundError:
        raise StgError(f"file `{file_path}` not found")

    # Parse patch file
    msg = ''
    author_name = get_user_name()
    author_email = get_user_email()
    author_date = now
    diff_start = 0

    lines = content.split('\n')
    i = 0
    msg_lines = []

    # Look for subject header
    while i < len(lines):
        line = lines[i]
        if line.startswith('Subject: '):
            subject = line[9:]
            # Remove [PATCH ...] prefix
            subject = re.sub(r'^\[PATCH[^\]]*\]\s*', '', subject)
            msg_lines.append(subject)
        elif line.startswith('From: '):
            m = re.match(r'From: (.*?)\s*<([^>]*)>', line)
            if m:
                author_name = m.group(1).strip()
                author_email = m.group(2)
        elif line.startswith('Date: '):
            # Parse email date
            pass
        elif line == '---':
            break
        elif line.startswith('diff ') or line.startswith('--- '):
            diff_start = i
            break
        elif msg_lines:
            msg_lines.append(line)
        i += 1

    msg = '\n'.join(msg_lines).strip()
    if not msg:
        # Use filename as message
        basename = os.path.basename(file_path)
        # Remove number prefix and extension
        basename = re.sub(r'^\d+-', '', basename)
        basename = re.sub(r'\.\w+$', '', basename)
        msg = basename.replace('-', ' ').replace('_', ' ')

    if name is None:
        basename = os.path.basename(file_path)
        basename = re.sub(r'\.\w+$', '', basename)
        pname = slugify_patch_name(basename)
    else:
        pname = name

    if ignore and state.patch_exists(pname):
        return
    if replace and state.patch_exists(pname):
        # Remove old patch
        if pname in state.unapplied:
            state.unapplied.remove(pname)
        del state.patches[pname]

    if state.patch_exists(pname):
        raise StgError(f"patch `{pname}` already exists")

    # Apply the diff
    apply_cmd = ['apply', f'-p{strip}']
    if reject:
        apply_cmd.append('--reject')
    if threeway:
        apply_cmd.append('--3way')
    apply_cmd.append('-')

    result = git(*apply_cmd, input=content.encode(), check=False)
    if result.returncode != 0:
        if reject:
            print(f"warning: some hunks rejected for {pname}", file=sys.stderr)
        else:
            raise StgError(f"patch `{pname}` does not apply cleanly")

    new_tree = git_output('write-tree')
    current_head = state.head
    current_info = get_commit_info(current_head)
    parent_tree = current_info['tree']

    new_oid = make_commit(
        new_tree, [current_head],
        author_name, author_email, author_date,
        get_user_name(), get_user_email(), now,
        msg
    )

    state.applied.append(pname)
    state.patches[pname] = new_oid
    state.head = new_oid

    desc = PatchDescriptor(
        bottom=parent_tree,
        top=new_tree,
        author_name=author_name,
        author_email=author_email,
        author_date=author_date,
        message=msg
    )
    stack._patch_descs[pname] = desc

    update_ref(f'refs/heads/{stack.branch}', new_oid)
    stack.save_state(state, f"import {pname}", now)

    print(f"> {pname}")

def _import_mail(stack, state, content, name, strip, threeway, reject, message_id, now):
    """Import from mail/mbox format"""
    # Split into individual mails if mbox
    if isinstance(content, bytes):
        content = content.decode('utf-8', errors='replace')

    # Simple mbox parser
    mails = []
    current = []
    for line in content.split('\n'):
        if line.startswith('From ') and current:
            mails.append('\n'.join(current))
            current = [line]
        else:
            current.append(line)
    if current:
        mails.append('\n'.join(current))

    for mail in mails:
        if not mail.strip():
            continue
        _import_mail_single(stack, state, mail, name, strip, threeway, reject, message_id, now)

def _import_mail_single(stack, state, mail, name, strip, threeway, reject, message_id, now):
    """Import a single mail patch"""
    lines = mail.split('\n')
    subject = ''
    author_name = get_user_name()
    author_email = get_user_email()
    author_date = now
    msg_id = ''

    in_headers = True
    body_lines = []

    for line in lines:
        if in_headers:
            if not line:
                in_headers = False
            elif line.startswith('Subject: '):
                subject = line[9:]
                subject = re.sub(r'^\[PATCH[^\]]*\]\s*', '', subject).strip()
            elif line.startswith('From: '):
                m = re.match(r'From: (.*?)\s*<([^>]*)>', line)
                if m:
                    author_name = m.group(1).strip()
                    author_email = m.group(2)
            elif line.startswith('Date: '):
                pass
            elif line.startswith('Message-ID: ') or line.startswith('Message-Id: '):
                msg_id = line.split(': ', 1)[1].strip()
        else:
            body_lines.append(line)

    body = '\n'.join(body_lines)

    # Extract message and diff
    msg_lines = []
    diff_start = None

    for i, line in enumerate(body_lines):
        if line == '---' or line.startswith('diff ') or line.startswith('--- '):
            diff_start = i
            break
        msg_lines.append(line)

    desc = '\n'.join(msg_lines).strip()
    if not desc and subject:
        desc = subject

    if message_id and msg_id:
        desc += f"\n\nMessage-ID: {msg_id}"

    if diff_start is not None:
        diff_text = '\n'.join(body_lines[diff_start:])
    else:
        diff_text = body

    if name is None:
        pname = slugify_patch_name(subject or desc.split('\n')[0])
    else:
        pname = name

    if not diff_text.strip():
        return

    apply_cmd = ['apply', f'-p{strip}']
    if reject:
        apply_cmd.append('--reject')
    apply_cmd.append('-')

    result = git(*apply_cmd, input=diff_text.encode(), check=False)
    if result.returncode != 0:
        if reject:
            print(f"warning: some hunks rejected for {pname}", file=sys.stderr)
        else:
            raise StgError(f"patch `{pname}` does not apply cleanly")

    new_tree = git_output('write-tree')
    current_head = state.head
    current_info = get_commit_info(current_head)
    parent_tree = current_info['tree']

    new_oid = make_commit(
        new_tree, [current_head],
        author_name, author_email, author_date,
        get_user_name(), get_user_email(), now,
        desc
    )

    state.applied.append(pname)
    state.patches[pname] = new_oid
    state.head = new_oid

    desc_obj = PatchDescriptor(
        bottom=parent_tree,
        top=new_tree,
        author_name=author_name,
        author_email=author_email,
        author_date=author_date,
        message=desc
    )
    stack._patch_descs[pname] = desc_obj

    update_ref(f'refs/heads/{stack.branch}', new_oid)
    stack.save_state(state, f"import {pname}", now)

    print(f"> {pname}")


def cmd_export(args):
    args = get_color_opt(args)
    if '--help' in args or '-h' in args:
        print("Export patches to a directory.")
        return

    branch = None
    output_dir = None
    numbered = False
    extension = None
    patch_suffix = False
    template_file = None
    to_stdout = False
    diff_opts = []
    patch_names = []

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-b', '--branch'):
            i += 1
            if i < len(args):
                branch = args[i]
        elif arg.startswith('--branch='):
            branch = arg[9:]
        elif arg in ('-d', '--dir'):
            i += 1
            if i < len(args):
                output_dir = args[i]
        elif arg.startswith('--dir='):
            output_dir = arg[6:]
        elif arg in ('-n', '--numbered'):
            numbered = True
        elif arg in ('-e', '--extension'):
            i += 1
            if i < len(args):
                extension = args[i]
        elif arg.startswith('--extension='):
            extension = arg[12:]
        elif arg in ('-p', '--patch'):
            patch_suffix = True
        elif arg in ('-t', '--template'):
            i += 1
            if i < len(args):
                template_file = args[i]
        elif arg.startswith('--template='):
            template_file = arg[11:]
        elif arg in ('-s', '--stdout'):
            to_stdout = True
        elif arg in ('-O', '--diff-opt'):
            i += 1
            if i < len(args):
                diff_opts.append(args[i])
        elif arg.startswith('--diff-opt='):
            diff_opts.append(arg[11:])
        elif arg.startswith('-'):
            pass
        else:
            patch_names.append(arg)
        i += 1

    if branch is None:
        branch = get_current_branch()
        if branch is None:
            raise StgError("not on a branch")

    stack = Stack(branch)
    if not stack.is_initialized():
        raise StgError(f"branch `{branch}` is not initialized")

    state = stack.get_state()

    if not patch_names:
        to_export = list(state.applied)
    else:
        to_export = patch_names

    if output_dir is None and not to_stdout:
        output_dir = f'patches-{branch}'

    if output_dir and not to_stdout:
        os.makedirs(output_dir, exist_ok=True)

    # Load template
    tmpl = None
    if template_file:
        with open(template_file) as f:
            tmpl = f.read()
    else:
        # Look for default template
        git_dir = get_git_dir()
        for tpath in [
            os.path.join(git_dir, 'patchexport.tmpl'),
            os.path.expanduser('~/.stgit/templates/patchexport.tmpl'),
        ]:
            if os.path.exists(tpath):
                with open(tpath) as f:
                    tmpl = f.read()
                break

    # Write series file
    if not to_stdout and output_dir:
        base_commit = state.get_base()
        series_content = f"# This series applies on Git commit {base_commit}\n"
        series_content += '\n'.join(to_export) + '\n'
        with open(os.path.join(output_dir, 'series'), 'w') as f:
            f.write(series_content)

    for idx, pname in enumerate(to_export):
        if not state.patch_exists(pname):
            raise StgError(f"patch `{pname}` does not exist")

        oid = state.patches[pname]
        info = get_commit_info(oid)
        author = info['author']
        msg = info.get('message', '').strip()

        parent = info['parents'][0] if info.get('parents') else None

        # Get diff
        if parent:
            diff_result = git('diff', parent, oid, *diff_opts, check=False)
        else:
            diff_result = git('show', '--patch', oid, *diff_opts, check=False)

        diff_text = diff_result.stdout.decode()

        # Get diffstat
        if parent:
            stat_result = git('diff', '--stat', parent, oid, check=False)
        else:
            stat_result = subprocess.CompletedProcess([], 0, b'', b'')
        stat_text = stat_result.stdout.decode() if stat_result.returncode == 0 else ''

        # Build patch content
        short_msg = msg.split('\n')[0]
        long_msg = '\n'.join(msg.split('\n')[1:]).strip()

        date_str = author['date'].strftime('%Y-%m-%dT%H:%M:%S %z') if isinstance(author['date'], datetime) else str(author['date'])

        if tmpl:
            content = tmpl % {
                'description': msg,
                'shortdescr': short_msg,
                'longdescr': long_msg,
                'diffstat': stat_text.rstrip(),
                'authname': author['name'],
                'authemail': author['email'],
                'authdate': date_str,
                'commname': get_user_name(),
                'commemail': get_user_email(),
            }
            content += diff_text
        else:
            # Default format
            content = f"{msg}\n\n"
            content += f"From: {author['name']} <{author['email']}>\n"
            content += "\n"
            content += "---\n"
            if stat_text:
                content += stat_text
                content += "\n"
            content += diff_text

        # Determine filename
        if numbered:
            prefix = f"{idx+1:04d}-"
        else:
            prefix = ""

        fname = prefix + pname
        if patch_suffix:
            fname += '.patch'
        elif extension:
            fname += f'.{extension}'

        if to_stdout:
            sys.stdout.write(content)
        else:
            with open(os.path.join(output_dir, fname), 'w') as f:
                f.write(content)


def cmd_pull(args):
    args = get_color_opt(args)
    if '--help' in args or '-h' in args:
        print("Pull changes from a remote repository.")
        return

    nopush = False
    merged = False
    conflicts_policy = 'allow'
    remote = None

    for arg in args:
        if arg in ('-n', '--nopush'):
            nopush = True
        elif arg in ('-m', '--merged'):
            merged = True
        elif not arg.startswith('-'):
            remote = arg

    branch = get_current_branch()
    if branch is None:
        raise StgError("not on a branch")

    stack = Stack(branch)
    if not stack.is_initialized():
        raise StgError(f"branch `{branch}` is not initialized")

    state = stack.get_state()
    now = datetime.now(tz=timezone.utc)

    # Pop all applied patches
    applied = list(state.applied)
    if applied:
        # Pop all
        for p in reversed(applied):
            state.applied.remove(p)
            state.unapplied.insert(0, p)

        base = state.get_base()
        state.head = base
        update_ref(f'refs/heads/{branch}', base)

    # Do the pull
    pull_args = ['pull']
    if remote:
        pull_args.append(remote)

    result = git(*pull_args, capture=False, check=False)
    if result.returncode != 0:
        raise StgError("git pull failed")

    # Update base
    new_head = get_head()
    state.head = new_head

    if not nopush:
        # Re-push patches
        for pname in list(state.unapplied[:len(applied)]):
            _push_single(stack, state, pname, now)

        update_ref(f'refs/heads/{branch}', state.head)

    stack.save_state(state, "pull", now)


def cmd_rebase(args):
    args = get_color_opt(args)
    if '--help' in args or '-h' in args:
        print("Move the stack base to another point in history.")
        return

    interactive = False
    nopush = False
    merged = False
    committer_date_is_author = False
    autostash = False
    conflicts_policy = 'allow'
    exec_cmds = []
    committish = None

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-i', '--interactive'):
            interactive = True
        elif arg in ('-n', '--nopush'):
            nopush = True
        elif arg in ('-m', '--merged'):
            merged = True
        elif arg == '--committer-date-is-author-date':
            committer_date_is_author = True
        elif arg == '--autostash':
            autostash = True
        elif arg.startswith('--conflicts'):
            pass
        elif arg in ('-x', '--exec'):
            i += 1
            if i < len(args):
                exec_cmds.append(args[i])
        elif arg.startswith('--exec='):
            exec_cmds.append(arg[7:])
        elif arg.startswith('-'):
            pass
        else:
            committish = arg
        i += 1

    branch = get_current_branch()
    if branch is None:
        raise StgError("not on a branch")

    stack = Stack(branch)
    if not stack.is_initialized():
        raise StgError(f"branch `{branch}` is not initialized")

    state = stack.get_state()
    now = datetime.now(tz=timezone.utc)

    if committish is None:
        # Try to get tracking branch
        remote = get_config(f'branch.{branch}.remote')
        merge = get_config(f'branch.{branch}.merge')
        if remote and merge:
            ref = merge.replace('refs/heads/', f'refs/remotes/{remote}/')
            committish = ref
        else:
            raise StgError("no committish specified and no tracking branch configured")

    new_base = git_output('rev-parse', '--verify', committish)

    # Pop all applied patches
    applied = list(state.applied)
    if applied:
        if len(applied) > 1:
            print(f"- {applied[0]}..{applied[-1]}")
        for p in reversed(applied):
            state.applied.remove(p)
            state.unapplied.insert(0, p)

        state.head = new_base
    else:
        state.head = new_base

    # Update HEAD
    update_ref(f'refs/heads/{branch}', new_base)

    if not nopush:
        # Re-push patches
        for pname in list(state.unapplied[:len(applied)]):
            _push_single(stack, state, pname, now)

            if exec_cmds:
                for cmd in exec_cmds:
                    result = subprocess.run(cmd, shell=True)
                    if result.returncode != 0:
                        # Rollback
                        raise StgError(f"exec command failed: {cmd}")

        update_ref(f'refs/heads/{branch}', state.head)

    stack.save_state(state, "rebase", now)


