def cmd_email(args):
    args = get_color_opt(args)

    if not args or args[0] in ('-h', '--help'):
        print_email_help()
        return

    subcmd = args[0]
    subcmd_args = args[1:]

    if subcmd == 'format':
        cmd_email_format(subcmd_args)
    elif subcmd == 'send':
        cmd_email_send(subcmd_args)
    elif subcmd in ('help', '--help', '-h'):
        if subcmd_args:
            print_email_help()
        else:
            print_email_help()
    else:
        raise StgError(f"unknown email subcommand `{subcmd}`")

def cmd_email_format(args):
    if '--help' in args or '-h' in args:
        print("Format patches as email files.")
        return

    branch = None
    fmt_all = False
    git_opts = []
    output_dir = None
    cover_letter = False
    numbered = False
    no_numbered = False
    start_number = None
    reroll_count = None
    rfc = False
    subject_prefix = None
    to = []
    cc = []
    patch_names = []

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-b', '--branch'):
            i += 1
            if i < len(args):
                branch = args[i]
        elif arg.startswith('--branch='):
            branch = arg[9:]
        elif arg in ('-a', '--all'):
            fmt_all = True
        elif arg in ('-G', '--git-opt'):
            i += 1
            if i < len(args):
                git_opts.append(args[i])
        elif arg.startswith('--git-opt='):
            git_opts.append(arg[10:])
        elif arg in ('-o', '--output-directory'):
            i += 1
            if i < len(args):
                output_dir = args[i]
        elif arg.startswith('--output-directory='):
            output_dir = arg[19:]
        elif arg == '--cover-letter':
            cover_letter = True
        elif arg in ('-n', '--numbered'):
            numbered = True
        elif arg in ('-N', '--no-numbered'):
            no_numbered = True
        elif arg.startswith('--start-number='):
            start_number = int(arg[15:])
        elif arg in ('-v', '--reroll-count'):
            i += 1
            if i < len(args):
                reroll_count = args[i]
        elif arg.startswith('--reroll-count='):
            reroll_count = arg[15:]
        elif arg == '--rfc':
            rfc = True
        elif arg.startswith('--subject-prefix='):
            subject_prefix = arg[17:]
        elif arg.startswith('--to='):
            to.append(arg[5:])
        elif arg == '--to':
            i += 1
            if i < len(args):
                to.append(args[i])
        elif arg.startswith('--cc='):
            cc.append(arg[5:])
        elif arg == '--cc':
            i += 1
            if i < len(args):
                cc.append(args[i])
        elif arg.startswith('-'):
            pass
        else:
            patch_names.append(arg)
        i += 1

    if branch is None:
        branch = get_current_branch()
        if branch is None:
            raise StgError("not on a branch")

    stack = Stack(branch)
    if not stack.is_initialized():
        raise StgError(f"branch `{branch}` is not initialized")

    state = stack.get_state()

    if fmt_all:
        to_format = list(state.applied)
    elif patch_names:
        to_format = patch_names
    else:
        raise StgError("no patches specified")

    # Build git format-patch command
    cmd_args = ['format-patch']
    if output_dir:
        cmd_args += ['-o', output_dir]
    if cover_letter:
        cmd_args.append('--cover-letter')
    if numbered:
        cmd_args.append('-n')
    if no_numbered:
        cmd_args.append('-N')
    if start_number:
        cmd_args += [f'--start-number={start_number}']
    if reroll_count:
        cmd_args += [f'-v{reroll_count}']
    if rfc:
        cmd_args.append('--rfc')
    if subject_prefix:
        cmd_args += [f'--subject-prefix={subject_prefix}']
    for t in to:
        cmd_args += [f'--to={t}']
    for c in cc:
        cmd_args += [f'--cc={c}']
    cmd_args += git_opts

    # Get the commits to format
    # Find base and HEAD
    commits = [state.patches[p] for p in to_format if state.patch_exists(p)]
    if not commits:
        raise StgError("no valid patches to format")

    # Get the first patch's parent as base
    first_oid = commits[0]
    first_info = get_commit_info(first_oid)
    base = first_info['parents'][0] if first_info.get('parents') else None
    last = commits[-1]

    if base:
        cmd_args.append(f'{base}..{last}')
    else:
        cmd_args.append(last)

    git(*cmd_args, capture=False)

