def cmd_completion_list(args):
    if not args or args[0] in ('-h', '--help'):
        print("List StGit command information.")
        return

    subcmd = args[0]
    subcmd_args = args[1:]

    style = 'name-only'
    output_file = None
    show_expansion = False

    i = 0
    while i < len(subcmd_args):
        arg = subcmd_args[i]
        if arg.startswith('--style='):
            style = arg[8:]
        elif arg == '--style':
            i += 1
            if i < len(subcmd_args):
                style = subcmd_args[i]
        elif arg in ('-o', '--output'):
            i += 1
            if i < len(subcmd_args):
                output_file = subcmd_args[i]
        elif arg.startswith('--output=') or arg.startswith('-o='):
            output_file = arg.split('=', 1)[1]
        elif arg == '--show-expansion':
            show_expansion = True
        i += 1

    # Command descriptions
    COMMANDS = [
        ('branch', 'Branch operations: switch, list, create, rename, delete, ...'),
        ('clean', 'Delete empty patches from the series'),
        ('commit', 'Finalize patches to the stack base'),
        ('completion', 'Support for shell completions'),
        ('delete', 'Delete patches'),
        ('diff', 'Show a diff'),
        ('edit', 'Edit a patch'),
        ('email', 'Format and send patches as email'),
        ('export', 'Export patches to a directory'),
        ('files', 'Show files modified by a patch'),
        ('float', 'Push patches to the top, even if applied'),
        ('fold', 'Fold diff file into the current patch'),
        ('goto', 'Go to patch by pushing or popping as necessary'),
        ('hide', 'Hide patches in the series'),
        ('id', 'Print git hash of a StGit revision'),
        ('import', 'Import patches to stack'),
        ('init', 'Initialize a StGit stack on a branch'),
        ('log', 'Display or optionally clear the stack changelog'),
        ('name', 'Print patch name of a StGit revision'),
        ('new', 'Create a new patch at top of the stack'),
        ('next', 'Print the name of the next patch'),
        ('patches', 'Show patches that modify files'),
        ('pick', 'Import a patch from another branch or a commit object'),
        ('pop', 'Pop (unapply) one or more applied patches'),
        ('prev', 'Print the name of the previous patch'),
        ('pull', 'Pull changes from a remote repository'),
        ('push', 'Push (apply) one or more unapplied patches'),
        ('rebase', 'Move the stack base to another point in history'),
        ('redo', 'Undo the last undo operation'),
        ('refresh', 'Incorporate worktree changes into current patch'),
        ('rename', 'Rename a patch'),
        ('repair', 'Repair stack after branch is modified with git commands'),
        ('reset', 'Reset the patch stack to an earlier state'),
        ('series', 'Display the patch series'),
        ('show', 'Show patch commits'),
        ('sink', 'Move patches deeper in the stack'),
        ('spill', 'Spill changes from the topmost patch'),
        ('squash', 'Squash two or more patches into one'),
        ('sync', 'Synchronize patches with a branch or a series'),
        ('top', 'Print the name of the top patch'),
        ('uncommit', 'Convert regular Git commits into StGit patches'),
        ('undo', 'Undo the last command'),
        ('unhide', 'Unhide hidden patches'),
        ('version', 'Print version information and exit'),
        ('help', 'Print this message or the help of the given subcommand(s)'),
    ]

    ALIASES = [
        ('add', 'git -C "$GIT_PREFIX" add', 'Alias for shell command `git -C "$GIT_PREFIX" add`'),
        ('mv', 'git -C "$GIT_PREFIX" mv', 'Alias for shell command `git -C "$GIT_PREFIX" mv`'),
        ('resolved', 'git -C "$GIT_PREFIX" add', 'Alias for shell command `git -C "$GIT_PREFIX" add`'),
        ('rm', 'git -C "$GIT_PREFIX" rm', 'Alias for shell command `git -C "$GIT_PREFIX" rm`'),
        ('status', 'git status -s', 'Alias for shell command `git status -s`'),
    ]

    output = []

    if subcmd == 'commands':
        if style == 'name-only':
            for name, desc in COMMANDS:
                output.append(name)
        elif style == 'fish' or style == 'zsh':
            sep = '\t' if style == 'fish' else ':'
            for name, desc in COMMANDS:
                output.append(f"{name}{sep}{desc}")
        elif style == 'asciidoc':
            # Group by category
            categories = [
                ('Patch Inspection', ['diff', 'files', 'id', 'log', 'name', 'show']),
                ('Patch Manipulation', ['edit', 'fold', 'new', 'refresh', 'rename', 'spill', 'sync']),
                ('Stack Inspection', ['email', 'export', 'next', 'patches', 'prev', 'series', 'top']),
                ('Stack Manipulation', ['branch', 'clean', 'commit', 'delete', 'float', 'goto', 
                                        'hide', 'import', 'init', 'pick', 'pop', 'pull', 'push',
                                        'rebase', 'redo', 'repair', 'reset', 'sink', 'squash',
                                        'uncommit', 'undo', 'unhide']),
                ('Administration', ['completion', 'version', 'help']),
            ]
            cmd_dict = dict(COMMANDS)
            for cat_name, cmd_list in categories:
                output.append(f"{cat_name}")
                output.append('~' * len(cat_name))
                output.append('')
                for name in cmd_list:
                    if name in cmd_dict:
                        output.append(f"linkstg:{name}[]::")
                        output.append(f"    {cmd_dict[name]}")
                output.append('')
    elif subcmd == 'aliases':
        if style == 'name-only':
            for name, exp, desc in ALIASES:
                output.append(name)
        elif style == 'fish':
            sep = '\t'
            for name, exp, desc in ALIASES:
                if show_expansion:
                    output.append(f"{name}{sep}!{exp}")
                else:
                    output.append(f"{name}{sep}{desc}")
        elif style == 'zsh':
            for name, exp, desc in ALIASES:
                if show_expansion:
                    output.append(f"{name}:!{exp}")
                else:
                    output.append(f"{name}:{desc}")
        elif style == 'asciidoc':
            output.append("Aliases")
            output.append("~~~~~~~")
            output.append("")
            for name, exp, desc in ALIASES:
                output.append(f"{name}::")
                if show_expansion:
                    output.append(f"    !{exp}")
                else:
                    output.append(f"    {desc}")
    elif subcmd == 'commands-and-aliases':
        if style == 'name-only':
            for name, desc in COMMANDS:
                output.append(name)
            for name, exp, desc in ALIASES:
                output.append(name)
        elif style == 'fish':
            for name, desc in COMMANDS:
                output.append(f"{name}\t{desc}")
            for name, exp, desc in ALIASES:
                if show_expansion:
                    output.append(f"{name}\t!{exp}")
                else:
                    output.append(f"{name}\t{desc}")
        elif style == 'zsh':
            for name, desc in COMMANDS:
                output.append(f"{name}:{desc}")
            for name, exp, desc in ALIASES:
                if show_expansion:
                    output.append(f"{name}:!{exp}")
                else:
                    output.append(f"{name}:{desc}")
    elif subcmd in ('help',):
        print("List StGit command information.")
        return
    else:
        raise StgError(f"unknown list subcommand `{subcmd}`")

    result_text = '\n'.join(output)

    if output_file:
