    for i, arg in enumerate(args):
        if arg in ('-o', '--output') and i + 1 < len(args):
            output_file = args[i + 1]
        elif arg.startswith('--output='):
            output_file = arg[9:]

    script = generate_fish_completion()

    if output_file:
        with open(output_file, 'w') as f:
            f.write(script)
    else:
        sys.stdout.write(script)

